function publicStreetAddress(address,hide,city='',district=''){let value=String(address||'').trim().replace(/[，,]/g,'').replace(/\s+/g,'');for(const prefix of [String(city||'')+String(district||''),String(city||''),String(district||'')])if(prefix&&value.startsWith(prefix)){value=value.slice(prefix.length);break}if(!hide)return value.slice(0,150);const alley=value.match(/^.*?\d+巷/);if(alley)return alley[0].slice(0,150);const streetName=value.match(/^.*?(?:大道|路|街|道)/);if(streetName){let road=streetName[0];const rest=value.slice(road.length),section=rest.match(/^[一二三四五六七八九十\d]+段/);if(section)road+=section[0];return road.slice(0,150)}return value.replace(/[\d].*$/,'').slice(0,150)}
