function listingQualityChecklist(form,photoCount=0){const value=name=>String(form.querySelector(`[name=\"${name}\"]`)?.value||'').trim(),category=value('market_category'),transaction=value('transaction_type'),bedrooms=value('bedrooms'),items=[{key:'title',label:'標題清楚具體（至少 12 字）',done:value('title').length>=12},{key:'description',label:'房屋介紹完整（至少 80 字）',done:value('description').length>=80},{key:'photos',label:'提供至少 3 張物件照片',done:photoCount>=3},{key:'location',label:'縣市、行政區與公開路名完整',done:['city','district','street'].every(k=>value(k))},{key:'contact',label:'提供電話或 LINE 聯絡方式',done:Boolean(value('phone')||value('line_id'))},{key:'price',label:['rent','wanted_rent'].includes(transaction)?'填寫每月租金／求租預算':'填寫出售／頂讓／求購價格',done:['rent','wanted_rent'].includes(transaction)?Number(value('monthly_rent'))>0:Number(value('asking_price'))>0}];let categoryLabel='補充物件型態或格局資料',categoryDone=false;if(category==='land'){categoryLabel='補充土地用途、使用分區與道路狀況';categoryDone=Boolean(value('land_type')&&value('zoning')&&value('land_access')&&value('land_access')!=='unknown')}else if(category==='new_development'){categoryLabel='補充建商、銷售狀態與預計交屋資料';categoryDone=Boolean(value('developer_name')&&value('project_status')&&value('handover_date'))}else if(category==='shop'||category==='office'){categoryLabel='補充商用業種與使用分區';categoryDone=Boolean(value('business_category')&&value('zoning'))}else if(category==='industrial'){categoryLabel='補充廠房淨高或電力規格';categoryDone=Boolean(value('warehouse_clear_height_m')||value('warehouse_power_kw'))}else if(category==='parking'){categoryLabel='補充車位型式與適用車種';categoryDone=Boolean(value('parking_type')&&value('parking_vehicle_limit'))}else categoryDone=Boolean(value('property_type')&&(value('layout')||bedrooms&&bedrooms!=='未提供'));items.push({key:'category',label:categoryLabel,done:categoryDone});return items}
