function agentProfileCard(a){return `<article class="panel agent-card"><p class="eyebrow">${esc(a.brokerage_name||'獨立經紀人')} ${a.is_verified?'<span class="verified-badge">好居已驗證</span>':''}</p><h2><a href="#/agent/${a.id}">${esc(a.display_name)}</a></h2><p>${esc((a.bio||'').slice(0,160))}${(a.bio||'').length>160?'…':''}</p><div class="tags">${(a.service_categories||[]).map(c=>`<span class="tag">${esc(agentCategoryLabels[c]||c)}</span>`).join('')}</div><small>${esc((a.service_areas||[]).join('、')||'服務區域洽詢經紀人')}</small><a class="button small" href="#/agent/${a.id}">查看店鋪與房源</a></article>`}
async function agentDirectoryPage(epoch){const agents=await result(db.from('agent_profiles').select('id,display_name,brokerage_name,bio,service_areas,service_categories,is_verified').order('display_name').limit(500));if(epoch!==routeEpoch)return;app.innerHTML=`<section class="intro"><div><div class="eyebrow">AGENT DIRECTORY</div><h1>找經紀人</h1><p>搜尋好居已審核的個人服務頁，查看服務市場、區域與公開刊登。</p></div><a class="button" href="#/agent/manage">申請／管理店鋪</a></section><form id="agent-directory-filter" class="panel agent-directory-filter"><label>經紀人或品牌<input name="q" maxlength="100" placeholder="姓名、品牌或服務區域"></label><label>服務市場<select name="category"><option value="">全部市場</option>${brokerageCategories.map(([v,l])=>`<option value="${v}">${l}</option>`).join('')}</select></label><button class="button primary">搜尋</button><button class="button" type="reset">清除</button></form><p class="muted" id="agent-result-count"></p><div class="agent-grid" id="agent-grid">${agents.map(a=>`<div data-agent-search="${esc([a.display_name,a.brokerage_name,...(a.service_areas||[])].join(' ').toLowerCase())}" data-agent-categories="${esc((a.service_categories||[]).join(','))}">${agentProfileCard(a)}</div>`).join('')}</div>${agents.length?'':'<div class="empty"><h2>目前還沒有公開經紀人</h2><p>完成好居審核後，經紀人服務頁就會出現在這裡。</p></div>'}`;const form=$('#agent-directory-filter'),cards=[...app.querySelectorAll('#agent-grid>[data-agent-search]')],apply=()=>{const q=form.querySelector('[name=q]').value.trim().toLowerCase(),cat=form.querySelector('[name=category]').value;let count=0;for(const el of cards){const show=(!q||el.dataset.agentSearch.includes(q))&&(!cat||el.dataset.agentCategories.split(',').includes(cat));el.hidden=!show;if(show)count++}$('#agent-result-count').textContent=`找到 ${count} 位經紀人`};form.onsubmit=e=>{e.preventDefault();apply()};form.onreset=()=>setTimeout(apply,0);apply()}
async function agentPage(id,epoch){const a=await result(db.from('agent_profiles').select('id,display_name,brokerage_name,bio,phone,line_id,service_areas,service_categories,is_verified,published_at').eq('id',id).maybeSingle());if(!a){app.innerHTML='<div class="empty"><h2>找不到這位經紀人</h2><a class="button" href="#/agents">返回經紀人名錄</a></div>';return}const listings=await result(db.from('listings').select('id,title,city,district,transaction_type,market_category,monthly_rent,asking_price,price_unit,area_ping,status').eq('agent_profile_id',id).eq('status','published').order('updated_at',{ascending:false}).limit(100));if(epoch!==routeEpoch)return;app.innerHTML=`<div class="breadcrumb"><a href="#/agents">找經紀人</a> ／ ${esc(a.display_name)}</div><section class="agent-profile-hero panel"><div><p class="eyebrow">${a.is_verified?'<span class="verified-badge">好居已驗證經紀人</span>':'HAŌJU AGENT'}</p><h1>${esc(a.display_name)}</h1><p class="agent-brand">${esc(a.brokerage_name||'獨立經紀人')}</p><div class="tags">${a.service_categories.map(c=>`<span class="tag">${esc(agentCategoryLabels[c]||c)}</span>`).join('')}</div><p>服務區域：${esc(a.service_areas.join('、')||'歡迎洽詢')}</p></div><div class="agent-contacts">${a.phone?`<a class="button primary" href="tel:${encodeURIComponent(a.phone)}">電話聯絡</a>`:''}${a.line_id?`<a class="button" target="_blank" rel="noopener noreferrer" href="https://line.me/R/ti/p/~${encodeURIComponent(a.line_id)}">LINE 聯絡</a>`:''}</div></section><section class="detail-section"><h2>經紀人介紹</h2><p class="pre-wrap">${esc(a.bio||'尚未提供介紹。')}</p></section><section class="admin-section"><h2>公開刊登（${listings.length}）</h2>${listings.map(l=>`<article class="agent-listing-row"><div><h3><a href="#/listing/${l.id}" target="_blank" rel="noopener">${esc(l.title)}</a></h3><p>${esc(l.city||'')}${esc(l.district||'')} · ${esc(categoryLabel(l.market_category))}／${esc(transactionLabel(l.transaction_type))} · ${Number(l.area_ping||0)} 坪</p></div><strong>${marketPrice(l)}</strong></article>`).join('')||'<p class="muted">目前沒有公開房源。</p>'}</section>`}
async function agentManagePage(epoch){if(!requireUser())return;const [profile,requests]=await Promise.all([result(db.from('agent_profiles').select('id,user_id,display_name,brokerage_name,bio,phone,line_id,service_areas,service_categories,is_verified').eq('user_id',user.id).maybeSingle()),result(db.from('agent_verification_requests').select('id,display_name,brokerage_name,status,admin_note,created_at').eq('user_id',user.id).order('created_at',{ascending:false}).limit(20))]);if(epoch!==routeEpoch)return;const latest=requests[0],pending=latest&&['pending','reviewing'].includes(latest.status),areas=profile?.service_areas||latest?.service_areas||[];const profileForm=profile?`<section class="admin-section"><h2>公開店鋪資料</h2><p>好居已審核你的服務頁。你可以自行更新公開介紹、聯絡方式與服務範圍。</p><form id="agent-profile-form" class="form-section"><label class="modal-label">公開姓名<input name="display_name" required minlength="2" maxlength="80" value="${esc(profile.display_name)}"></label><label class="modal-label">仲介品牌／公司<input name="brokerage_name" maxlength="120" value="${esc(profile.brokerage_name)}"></label><label class="modal-label">公開介紹<textarea name="bio" maxlength="2000" rows="5">${esc(profile.bio)}</textarea></label><label class="modal-label">公開電話<input name="phone" type="tel" maxlength="40" value="${esc(profile.phone)}"></label><label class="modal-label">LINE ID<input name="line_id" maxlength="100" value="${esc(profile.line_id)}"></label><label class="modal-label">服務區域（頓號或逗號分隔）<input name="service_areas" maxlength="1000" value="${esc(profile.service_areas.join('、'))}"></label><fieldset><legend>服務市場</legend>${brokerageCategories.map(([v,l])=>`<label><input type="checkbox" name="service_categories" value="${v}" ${profile.service_categories.includes(v)?'checked':''}> ${l}</label> `).join('')}</fieldset><button class="button primary">更新店鋪</button><p id="agent-profile-result" class="muted" role="status"></p><a class="link" href="#/agent/${profile.id}">查看公開頁 →</a></form></section>`:'';app.innerHTML=`<div class="breadcrumb"><a href="#/account">我的帳號</a> ／ <a href="#/agents">經紀人名錄</a> ／ 店鋪管理</div><section class="intro"><div><div class="eyebrow">AGENT STORE</div><h1>經紀人店鋪管理</h1><p>提交服務資料並由好居人工審核，通過後可管理公開服務頁。</p></div></section>${profileForm}${!profile?`<section class="admin-section"><h2>${pending?'申請審核中':'申請建立經紀人服務頁'}</h2>${pending?`<p>申請狀態：${latest.status==='reviewing'?'好居審核中':'等待審核'} · ${new Date(latest.created_at).toLocaleDateString('zh-TW')}</p>${latest.admin_note?`<p class="notice">審查意見：${esc(latest.admin_note)}</p>`:''}<p>核准後，你的姓名、品牌、介紹與聯絡方式將公開於經紀人服務頁。你可隨時更新公開資料。請勿提交身分證字號、證照號碼或證件影像。</p>`:`<form id="agent-application-form" class="form-section"><label class="modal-label">公開姓名<input name="display_name" required minlength="2" maxlength="80"></label><label class="modal-label">仲介品牌／公司（選填）<input name="brokerage_name" maxlength="120"></label><label class="modal-label">公開聯絡電話<input name="contact_phone" type="tel" required minlength="6" maxlength="40"></label><label class="modal-label">LINE ID（選填）<input name="line_id" maxlength="100"></label><label class="modal-label">服務介紹<textarea name="bio" maxlength="2000" rows="4"></textarea></label><label class="modal-label">服務區域（頓號或逗號分隔）<input name="service_areas" maxlength="1000" placeholder="例如：台北市大安區、新北市板橋區"></label><fieldset><legend>服務市場</legend>${brokerageCategories.map(([v,l])=>`<label><input type="checkbox" name="service_categories" value="${v}"> ${l}</label> `).join('')}</fieldset><label class="modal-label">認證補充說明<textarea name="verification_note" required minlength="10" maxlength="1200" rows="4" placeholder="說明你的經紀服務身分，以及好居管理員可以透過何種公開方式核對。不要填寫身分證字號或證照號碼。"></textarea></label><label class="privacy-consent"><input type="checkbox" name="agent-consent" required> 我同意以上聯絡資料在審核通過後公開，並供找房會員聯絡。</label><button class="button primary">送出人工審核</button><p id="agent-application-result" class="muted" role="status"></p></form>`}</section>`:''}<section class="admin-section"><h2>申請紀錄（${requests.length}）</h2>${requests.map(r=>`<article class="panel"><strong>${esc(r.display_name)} · ${{pending:'等待審核',reviewing:'審核中',approved:'已核准',rejected:'未核准'}[r.status]||r.status}</strong><p>${esc(r.brokerage_name||'獨立經紀人')} · ${new Date(r.created_at).toLocaleDateString('zh-TW')}</p>${r.admin_note?`<p class="notice">${esc(r.admin_note)}</p>`:''}</article>`).join('')||'<p class="muted">尚無申請紀錄。</p>'}</section>`;
 const appForm=$('#agent-application-form');if(appForm)appForm.onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button'),get=n=>f.querySelector(`[name="${n}"]`).value.trim(),areas=get('service_areas').split(/[、,，]/).map(x=>x.trim()).filter(Boolean),categories=[...f.querySelectorAll('[name="service_categories"]')].filter(x=>x.checked).map(x=>x.value);if(!categories.length){$('#agent-application-result').textContent='請至少選擇一項服務市場。';return}b.disabled=true;try{await result(db.from('agent_verification_requests').insert({user_id:user.id,display_name:get('display_name'),brokerage_name:get('brokerage_name'),contact_phone:get('contact_phone'),line_id:get('line_id'),bio:get('bio'),service_areas:areas,service_categories:categories,verification_note:get('verification_note')}));toast('申請已送出');await route()}catch(err){$('#agent-application-result').textContent=message(err);b.disabled=false}};
 const profForm=$('#agent-profile-form');if(profForm)profForm.onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button'),get=n=>f.querySelector(`[name="${n}"]`).value.trim();b.disabled=true;try{const rows=await result(db.from('agent_profiles').update({display_name:get('display_name'),brokerage_name:get('brokerage_name'),bio:get('bio'),phone:get('phone'),line_id:get('line_id'),service_areas:get('service_areas').split(/[、,，]/).map(x=>x.trim()).filter(Boolean),service_categories:[...f.querySelectorAll('[name="service_categories"]')].filter(x=>x.checked).map(x=>x.value)}).eq('user_id',user.id).select('user_id'));if(!rows?.length)throw Error('店鋪資料未儲存。');$('#agent-profile-result').textContent='公開資料已更新。'}catch(err){$('#agent-profile-result').textContent=message(err)}finally{b.disabled=false}}}
async function agentAdminPage(epoch){if(!requireUser())return;if(!isAdmin){app.innerHTML='<div class="empty"><h2>此頁僅供好居管理員使用</h2></div>';return}const rows=await result(db.from('agent_verification_requests').select('id,user_id,display_name,brokerage_name,contact_phone,line_id,bio,service_areas,service_categories,verification_note,status,admin_note,created_at').order('created_at',{ascending:false}).limit(300));if(epoch!==routeEpoch)return;app.innerHTML=`<div class="breadcrumb"><a href="#/admin">管理後台</a> ／ 經紀人申請</div><section class="intro"><div><div class="eyebrow">AGENT VERIFICATION</div><h1>經紀人申請審核</h1><p>申請資料只供好居管理員與申請會員本人查看；核准後會建立公開服務頁。</p></div></section>${rows.map(r=>`<article class="admin-card agent-review-card"><div><span class="tag">${{pending:'待審核',reviewing:'審核中',approved:'已核准',rejected:'未核准'}[r.status]||r.status}</span><h2>${esc(r.display_name)} · ${esc(r.brokerage_name||'獨立經紀人')}</h2><p>電話：${esc(r.contact_phone)}${r.line_id?' · LINE：'+esc(r.line_id):''}</p><p>${esc(r.bio||'未填寫介紹')}</p><p>服務區域：${esc(r.service_areas.join('、')||'未填寫')} · 市場：${r.service_categories.map(c=>esc(agentCategoryLabels[c]||c)).join('、')}</p><div class="review-note"><strong>會員的核對說明</strong><p>${esc(r.verification_note)}</p></div><label class="modal-label">管理員回覆<textarea data-agent-note="${r.id}" maxlength="1200" rows="2">${esc(r.admin_note)}</textarea></label><small>申請會員 ID：${esc(r.user_id)} · ${new Date(r.created_at).toLocaleString('zh-TW')}</small></div>${['pending','reviewing'].includes(r.status)?`<div class="manage-actions"><button class="button" data-agent-review="${r.id}" data-action="reviewing">標記處理中</button><button class="button primary" data-agent-review="${r.id}" data-action="approve">核准並公開</button><button class="button" data-agent-review="${r.id}" data-action="reject">婉拒</button></div>`:''}</article>`).join('')||'<div class="empty"><h2>目前沒有經紀人申請</h2></div>'}`;app.querySelectorAll('[data-agent-review]').forEach(b=>b.onclick=async()=>{b.disabled=true;const note=app.querySelector(`[data-agent-note="${b.dataset.agentReview}"]`).value.trim();try{await result(db.rpc('haoju_review_agent_application',{p_request_id:b.dataset.agentReview,p_action:b.dataset.action,p_admin_note:note}));toast('申請狀態已更新');await route()}catch(err){toast(message(err));b.disabled=false}})}

async function agencyIndex(epoch){const [rows,profiles]=await Promise.all([result(db.from('listings').select('id,title,city,district,brokerage_name,advertiser_type,transaction_type,market_category,monthly_rent,asking_price,price_unit').eq('status','published').neq('brokerage_name','').order('brokerage_name',{ascending:true}).limit(1000)),result(db.from('brokerage_profiles').select('id,brand_name,description,is_verified,service_areas,service_categories').order('brand_name',{ascending:true}).limit(500))]);if(epoch!==routeEpoch)return;const groups=new Map;for(const p of rows||[]){const name=String(p.brokerage_name||'').trim();if(!name)continue;if(!groups.has(name))groups.set(name,{name,count:0,items:[]});const g=groups.get(name);g.count++;if(g.items.length<3)g.items.push(p)}for(const profile of profiles||[]){const g=groups.get(profile.brand_name)||{name:profile.brand_name,count:0,items:[]};g.profile=profile;groups.set(profile.brand_name,g)}app.innerHTML=`<section class="page-head"><p class="eyebrow">AGENCY DIRECTORY</p><h1>仲介與建商品牌</h1><p>瀏覽品牌服務範圍、聯絡方式與公開房源。驗證標記由好居人工審查。</p></section>${groups.size?`<div class="community-grid">${[...groups.values()].map(g=>`<article class="panel community-card"><p class="eyebrow">${g.profile?.is_verified?'好居已驗證品牌':'公開房源品牌'}</p><h2><a href="#/agency/${encodeURIComponent(g.name)}">${esc(g.name)}</a></h2><p>${g.profile?.description?esc(g.profile.description):`${g.count} 筆公開房源`}</p>${g.profile?.service_areas?.length?`<p>服務區域：${esc(g.profile.service_areas.join('、'))}</p>`:''}<div>${g.items.map(p=>`<a class="link" href="#/listing/${p.id}" target="_blank" rel="noopener">${esc(p.title)} · ${marketPrice(p)}</a>`).join('<br>')}</div><a class="button" href="#/agency/${encodeURIComponent(g.name)}">查看品牌與房源</a></article>`).join('')}</div>`:'<div class="empty"><h2>目前尚無品牌房源</h2><p>品牌檔案與公開房源會顯示在這裡。</p><a class="button" href="#/rent">回到找房</a></div>'}`}

const brokerageCategories=[['rent','租屋'],['sale','住宅買賣'],['new_development','新建案'],['land','土地'],['shop','店面'],['office','辦公／住辦'],['industrial','廠房'],['parking','車位'],['business_transfer','店面頂讓']];const agentCategoryLabels=Object.fromEntries(brokerageCategories);
function brokerageClaimSection(profile,state){if(!user)return `<section class="admin-section"><h2>品牌資料由你管理嗎？</h2><p>登入後可提交品牌認領申請，由好居人工核對。</p><a class="button" href="#/account">登入申請</a></section>`;if(state==='claimed_by_me')return `<section class="admin-section"><h2>品牌資料管理</h2><p>品牌認領已通過。你可以維護公開介紹與服務方式；品牌名稱及驗證狀態由好居管理員管理。</p><form id="claimed-brokerage-form" class="form-section"><label class="modal-label">品牌介紹<textarea name="description" maxlength="3000" rows="4">${esc(profile.description||'')}</textarea></label><label class="modal-label">聯絡電話<input name="phone" maxlength="40" value="${esc(profile.phone||'')}"></label><label class="modal-label">LINE ID<input name="line_id" maxlength="100" value="${esc(profile.line_id||'')}"></label><label class="modal-label">品牌網站<input name="website" type="url" maxlength="300" value="${esc(profile.website||'')}"></label><label class="modal-label">服務區域（頓號分隔）<input name="service_areas" maxlength="1500" value="${esc((profile.service_areas||[]).join('、'))}"></label><fieldset><legend>服務類別</legend>${brokerageCategories.map(([v,l])=>`<label><input type="checkbox" name="service_categories" value="${v}" ${(profile.service_categories||[]).includes(v)?'checked':''}> ${l}</label> `).join('')}</fieldset><button class="button primary">儲存品牌資料</button></form></section>`;if(state==='pending_mine')return `<section class="admin-section"><h2>品牌認領申請</h2><p>申請已送出，等待好居管理員人工核對。處理結果會通知你。</p><a class="button" href="#/brokerage-claims">查看申請進度</a></section>`;if(state==='already_claimed'||state==='pending_by_other'||state==='verified')return `<section class="admin-section"><h2>品牌認領</h2><p>${state==='already_claimed'?'此品牌已由好居核准其他管理者認領。':state==='pending_by_other'?'此品牌已有一筆待審認領申請。':'此品牌已由好居完成驗證；如需更正，請聯絡好居管理員。'}</p></section>`;return `<section class="admin-section"><h2>認領這個品牌</h2><p>如果你是此仲介／建商品牌的負責人，提交公司信箱、聯絡資訊及授權說明。好居會人工核對，通過後你可維護品牌介紹與服務範圍。請勿填寫身分證字號或上傳含敏感個資的文件。</p><form id="brokerage-claim-form" class="form-section"><label class="modal-label">聯絡人<input name="contact_name" maxlength="100" required></label><label class="modal-label">職稱／與品牌的關係<input name="role_title" maxlength="100" required placeholder="例如：店東、品牌管理者"></label><label class="modal-label">公司電子郵件<input name="business_email" type="email" maxlength="254" required></label><label class="modal-label">聯絡電話<input name="contact_phone" type="tel" maxlength="40" required></label><label class="modal-label">授權與任職說明<textarea name="evidence_note" minlength="10" maxlength="1500" rows="4" required placeholder="說明你如何代表此品牌，以及管理員可透過何種公開管道核對"></textarea></label><label class="privacy-consent"><input type="checkbox" name="claim_consent" required> 我同意將上述資料提供給好居管理員進行品牌授權核對。</label><button class="button primary">送出認領申請</button></form><p><a class="link" href="#/brokerage-claims">查看我的申請紀錄 →</a></p></section>`}
function brokerageNameClaimSection(name){if(!user)return `<section class="admin-section"><h2>認領 ${esc(name)} 品牌</h2><p>登入後可提交品牌授權申請，由好居人工核對。</p><a class="button" href="#/account">登入申請</a></section>`;return `<section class="admin-section"><h2>認領 ${esc(name)} 品牌</h2><p>目前只有刊登資料，尚未建立品牌檔案。如果你是品牌負責人，提交公司信箱、聯絡資訊及授權說明；好居人工核對通過後即可維護品牌頁。請勿提供身分證字號或敏感文件。</p><form id="brokerage-name-claim-form" class="form-section"><label class="modal-label">聯絡人<input name="contact_name" maxlength="100" required></label><label class="modal-label">職稱／與品牌的關係<input name="role_title" maxlength="100" required></label><label class="modal-label">公司電子郵件<input name="business_email" type="email" maxlength="254" required></label><label class="modal-label">聯絡電話<input name="contact_phone" type="tel" maxlength="40" required></label><label class="modal-label">授權與任職說明<textarea name="evidence_note" minlength="10" maxlength="1500" rows="4" required></textarea></label><label class="privacy-consent"><input type="checkbox" name="claim_consent" required> 我同意將資料提供給好居管理員人工核對。</label><button class="button primary">送出認領申請</button></form></section>`}
function wireBrokerageNameClaim(name){const form=$('#brokerage-name-claim-form');if(!form)return;form.onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(form));if(!form.querySelector('[name=claim_consent]').checked)return;const button=form.querySelector('button');button.disabled=true;try{await result(db.rpc('haoju_create_brokerage_claim_by_name',{p_brand_name:name,p_contact_name:values.contact_name.trim(),p_role_title:values.role_title.trim(),p_business_email:values.business_email.trim(),p_contact_phone:values.contact_phone.trim(),p_evidence_note:values.evidence_note.trim(),p_consent:true}));toast('品牌認領已送出，等待人工核對');await route()}catch(err){toast(message(err));button.disabled=false}}}
function wireBrokerageClaim(profile,state){if(!profile||!user)return;const claim=$('#brokerage-claim-form');if(claim)claim.onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(claim));if(!claim.querySelector('[name=claim_consent]').checked)return;const button=claim.querySelector('button');button.disabled=true;try{await result(db.rpc('haoju_create_brokerage_claim',{p_brokerage_id:profile.id,p_contact_name:values.contact_name.trim(),p_role_title:values.role_title.trim(),p_business_email:values.business_email.trim(),p_contact_phone:values.contact_phone.trim(),p_evidence_note:values.evidence_note.trim(),p_consent:true}));toast('品牌認領已送出，等待人工核對');await route()}catch(err){toast(message(err));button.disabled=false}};const edit=$('#claimed-brokerage-form');if(edit)edit.onsubmit=async e=>{e.preventDefault();const fd=new FormData(edit),areas=String(fd.get('service_areas')||'').split(/[、,，]/).map(x=>x.trim()).filter(Boolean),categories=fd.getAll('service_categories'),button=edit.querySelector('button');if(areas.length>80){toast('服務區域最多 80 個');return}button.disabled=true;try{await result(db.rpc('haoju_update_claimed_brokerage_profile',{p_brokerage_id:profile.id,p_description:String(fd.get('description')||'').trim(),p_phone:String(fd.get('phone')||'').trim(),p_line_id:String(fd.get('line_id')||'').trim(),p_website:String(fd.get('website')||'').trim(),p_service_areas:areas,p_service_categories:categories}));toast('品牌資料已更新');await route()}catch(err){toast(message(err));button.disabled=false}}}
async function brokerageClaimsPage(epoch){if(!requireUser())return;const rows=await result(db.from('brokerage_claims').select('id,brokerage_id,contact_name,role_title,business_email,contact_phone,evidence_note,status,admin_note,reviewed_at,created_at,profile:brokerage_profiles(brand_name)').eq('claimant_id',user.id).order('created_at',{ascending:false}).limit(100));if(epoch!==routeEpoch)return;app.innerHTML=`<section class="intro"><div><div class="eyebrow">BRAND CLAIMS</div><h1>品牌認領申請</h1><p>追蹤你提交的品牌授權核對結果。</p></div></section>${rows.length?rows.map(c=>`<article class="manage-card"><div><span class="tag">${({pending:'等待人工核對',approved:'已核准',rejected:'未通過'})[c.status]||esc(c.status)}</span><h2>${esc(c.profile?.brand_name||'品牌')}</h2><p>${esc(c.contact_name)}・${esc(c.role_title)}・${esc(c.business_email)}</p><p>${esc(c.evidence_note)}</p>${c.admin_note?`<p><strong>好居回覆：</strong>${esc(c.admin_note)}</p>`:''}<small>申請時間 ${new Date(c.created_at).toLocaleString('zh-TW')}${c.reviewed_at?`・審核時間 ${new Date(c.reviewed_at).toLocaleString('zh-TW')}`:''}</small></div><a class="button" href="#/agency/${encodeURIComponent(c.profile?.brand_name||'')}">前往品牌頁</a></article>`).join(''):'<div class="empty"><h2>尚無品牌認領申請</h2><p>前往仲介／建商品牌頁，選擇「認領這個品牌」開始申請。</p><a class="button" href="#/agencies">瀏覽品牌名錄</a></div>'}`}
async function agencyPage(rawName,epoch){let name;try{name=decodeURIComponent(rawName)}catch{name=rawName}const [rows,profiles]=await Promise.all([result(db.from('listings').select(fields,{count:'exact'}).eq('status','published').eq('brokerage_name',name).order('created_at',{ascending:false}).limit(100)),result(db.from('brokerage_profiles').select('id,brand_name,description,phone,line_id,website,service_areas,service_categories,is_verified').eq('brand_name',name).limit(1))]);if(epoch!==routeEpoch)return;const items=await signedPhotos(rows||[]);if(epoch!==routeEpoch)return;const profile=profiles?.[0];let branches=[],claimState='';if(profile){branches=await result(db.from('brokerage_branches').select('name,city,district,street,phone,line_id,opening_hours').eq('brokerage_id',profile.id).order('city',{ascending:true}).limit(100));if(user)claimState=await result(db.rpc('haoju_brokerage_claim_status',{p_brokerage_id:profile.id}))}if(epoch!==routeEpoch)return;app.innerHTML=`<div class="breadcrumb"><a href="#/agencies">仲介與建商品牌</a> ／ ${esc(name)}</div><section class="page-head"><p class="eyebrow">AGENCY PROFILE ${profile?.is_verified?'・好居已驗證':''}</p><h1>${esc(name)}</h1><p>${profile?.description?esc(profile.description):'品牌與房源資訊由提供者填寫，請自行查核資格及交易條件。'}</p>${profile?`<p>${profile.service_areas?.length?`服務區域：${esc(profile.service_areas.join('、'))}　`:''}${profile.service_categories?.length?`服務類別：${esc(profile.service_categories.map(c=>({rent:'租屋',sale:'買賣',new_development:'新建案',land:'土地',shop:'店面',office:'辦公',industrial:'廠房',parking:'車位',business_transfer:'頂讓'}[c]||c)).join('、'))}`:''}</p><p>${profile.phone?`電話：<a href="tel:${esc(profile.phone)}">${esc(profile.phone)}</a>　`:''}${profile.line_id?`LINE：${esc(profile.line_id)}　`:''}${profile.website?`<a href="${esc(profile.website)}" target="_blank" rel="noopener">品牌網站</a>`:''}</p>`:''}</section>${profile?brokerageClaimSection(profile,claimState):items.length?brokerageNameClaimSection(name):''}${branches.length?`<section class="admin-section"><h2>服務門市</h2><div class="community-grid">${branches.map(b=>`<article class="panel"><h3>${esc(b.name)}</h3><p>${esc([b.city,b.district,b.street].filter(Boolean).join(''))}</p>${b.phone?`<p><a href="tel:${esc(b.phone)}">${esc(b.phone)}</a></p>`:''}${b.line_id?`<p>LINE：${esc(b.line_id)}</p>`:''}${b.opening_hours?`<p>${esc(b.opening_hours)}</p>`:''}</article>`).join('')}</div></section>`:''}<section class="admin-section"><h2>公開房源 (${items.length})</h2>${items.length?`<div class="cards">${items.map(card).join('')}</div>`:'<div class="empty"><p>目前沒有公開房源。</p><a class="button" href="#/agencies">返回品牌名錄</a></div>'}</section>`;wireBrokerageClaim(profile,claimState);if(!profile&&items.length)wireBrokerageNameClaim(name)}
async function brokerageAdminPage(epoch){if(!requireUser())return;if(!isAdmin){app.innerHTML='<div class="empty"><h2>此頁僅供好居管理員使用</h2></div>';return}const [profiles,branches,claims]=await Promise.all([result(db.from('brokerage_profiles').select('*').order('brand_name',{ascending:true}).limit(500)),result(db.from('brokerage_branches').select('*').order('city',{ascending:true}).limit(1000)),result(db.from('brokerage_claims').select('id,brokerage_id,claimant_id,contact_name,role_title,business_email,contact_phone,evidence_note,status,created_at,profile:brokerage_profiles(brand_name)').eq('status','pending').order('created_at',{ascending:true}).limit(300))]);if(epoch!==routeEpoch)return;const profileRows=profiles||[],branchRows=branches||[],claimRows=claims||[];app.innerHTML=`<section class="intro"><div class="eyebrow">BROKERAGE MANAGEMENT</div><h1>品牌與門市管理</h1><p>只供好居管理員維護；一般會員不能更改品牌資料或驗證狀態。</p><p><a class="button" href="#/admin">返回管理後台</a></p></section><section class="admin-section"><h2>新增／編輯品牌檔案</h2><form id="brokerage-profile-form" class="form-section"><input type="hidden" name="id"><label class="modal-label">品牌名稱<input name="brand_name" maxlength="120" required></label><label class="modal-label">品牌介紹<textarea name="description" maxlength="3000" rows="4"></textarea></label><label class="modal-label">電話<input name="phone" maxlength="40"></label><label class="modal-label">LINE ID<input name="line_id" maxlength="100"></label><label class="modal-label">網站（https://）<input name="website" type="url" maxlength="300"></label><label class="modal-label">服務區域（以頓號分隔）<input name="service_areas" maxlength="1500" placeholder="台北市、大安區、信義區"></label><fieldset><legend>服務類別</legend>${[['rent','租屋'],['sale','住宅買賣'],['new_development','新建案'],['land','土地'],['shop','店面'],['office','辦公／住辦'],['industrial','廠房'],['parking','車位'],['business_transfer','店面頂讓']].map(([v,l])=>`<label><input type="checkbox" name="service_categories" value="${v}"> ${l}</label> `).join('')}</fieldset><label><input type="checkbox" name="is_verified"> 好居已完成品牌資料查核</label><div class="form-actions"><button class="button primary">儲存品牌</button><button class="button" type="reset" id="brokerage-clear">清空</button></div><p id="brokerage-result" role="status"></p></form></section><section class="admin-section"><h2>待審品牌認領 (${claimRows.length})</h2>${claimRows.map(c=>`<article class="admin-card"><div><strong>${esc(c.profile?.brand_name||'品牌')}・${esc(c.contact_name)}（${esc(c.role_title)}）</strong><p>公司信箱：${esc(c.business_email)}・電話：${esc(c.contact_phone)}</p><p>${esc(c.evidence_note)}</p><small>申請者帳號：${esc(c.claimant_id)}・${new Date(c.created_at).toLocaleString('zh-TW')}</small></div><div class="manage-actions"><button class="button primary" data-review-claim="${c.id}" data-claim-status="approved">核准認領</button><button class="button" data-review-claim="${c.id}" data-claim-status="rejected">退回申請</button></div></article>`).join('')||'<p>沒有待審品牌認領。</p>'}</section><section class="admin-section"><h2>品牌檔案 (${profileRows.length})</h2>${profileRows.map(x=>`<article class="admin-card"><div><strong>${esc(x.brand_name)} ${x.is_verified?'・好居已驗證':''}</strong><p>${esc(x.service_areas?.join('、')||'未設定服務區域')}</p><a href="#/agency/${encodeURIComponent(x.brand_name)}">公開品牌頁</a></div><div class="manage-actions"><button class="button" data-edit-brokerage="${x.id}">編輯</button><button class="button" data-add-branch="${x.id}">新增門市</button></div></article>`).join('')||'<p>尚無品牌檔案。</p>'}</section><section class="admin-section"><h2>品牌門市 (${branchRows.length})</h2>${branchRows.map(b=>`<article class="admin-card"><div><strong>${esc(profileRows.find(x=>x.id===b.brokerage_id)?.brand_name||'品牌')}・${esc(b.name)}</strong><p>${esc([b.city,b.district,b.street].filter(Boolean).join(''))} ${b.phone?`・${esc(b.phone)}`:''}</p></div><div class="manage-actions"><button class="button" data-delete-branch="${b.id}">刪除門市</button></div></article>`).join('')||'<p>尚無門市資料。</p>'}</section>`;app.querySelectorAll('[data-review-claim]').forEach(b=>b.onclick=async()=>{const status=b.dataset.claimStatus;let note='品牌授權資訊已人工核對';if(status==='rejected'){note=prompt('請說明退回原因（至少 5 個字）','請補充品牌授權或公司任職證明資訊');if(note===null)return;if(note.trim().length<5){toast('請輸入至少 5 個字的退回原因');return}}else if(!confirm('請先人工核對公司信箱與品牌授權資訊，再核准品牌認領。繼續？'))return;b.disabled=true;try{await result(db.rpc('haoju_review_brokerage_claim',{p_claim_id:b.dataset.reviewClaim,p_status:status,p_admin_note:note}));toast(status==='approved'?'品牌認領已核准並驗證':'已退回品牌認領申請');await route()}catch(err){toast(message(err));b.disabled=false}});const form=$('#brokerage-profile-form');form.onsubmit=async e=>{e.preventDefault();const fd=new FormData(form),id=fd.get('id'),data={brand_name:String(fd.get('brand_name')).trim(),description:String(fd.get('description')||'').trim(),phone:String(fd.get('phone')||'').trim(),line_id:String(fd.get('line_id')||'').trim(),website:String(fd.get('website')||'').trim(),service_areas:String(fd.get('service_areas')||'').split(/[、,，]/).map(x=>x.trim()).filter(Boolean),service_categories:fd.getAll('service_categories'),is_verified:fd.get('is_verified')==='on',created_by:user.id};const q=id?db.from('brokerage_profiles').update(data).eq('id',id):db.from('brokerage_profiles').insert(data);try{await result(q);toast('品牌資料已儲存');await route()}catch(err){$('#brokerage-result').textContent=message(err)}};app.querySelectorAll('[data-edit-brokerage]').forEach(btn=>btn.onclick=()=>{const x=profileRows.find(p=>p.id===btn.dataset.editBrokerage);for(const k of ['id','brand_name','description','phone','line_id','website'])form.elements[k].value=x[k]||'';form.elements.service_areas.value=(x.service_areas||[]).join('、');form.elements.is_verified.checked=!!x.is_verified;form.querySelectorAll('[name="service_categories"]').forEach(c=>c.checked=(x.service_categories||[]).includes(c.value));form.scrollIntoView({behavior:'smooth'})});app.querySelectorAll('[data-add-branch]').forEach(btn=>btn.onclick=()=>{const x=profileRows.find(p=>p.id===btn.dataset.addBranch);modal(`新增 ${esc(x.brand_name)} 門市`,`<form id="branch-form" class="form-section"><label class="modal-label">門市名稱<input name="name" maxlength="120" required></label><label class="modal-label">縣市<input name="city" maxlength="20"></label><label class="modal-label">行政區<input name="district" maxlength="30"></label><label class="modal-label">地址<input name="street" maxlength="160"></label><label class="modal-label">電話<input name="phone" maxlength="40"></label><label class="modal-label">LINE ID<input name="line_id" maxlength="100"></label><label class="modal-label">營業時間<input name="opening_hours" maxlength="200"></label><button class="button primary">儲存門市</button></form>`);$('#branch-form').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.brokerage_id=x.id;d.created_by=user.id;try{await result(db.from('brokerage_branches').insert(d));$('#info').close();toast('門市已新增');await route()}catch(err){toast(message(err))}}});app.querySelectorAll('[data-delete-branch]').forEach(btn=>btn.onclick=async()=>{if(!confirm('確定刪除此門市？'))return;try{await result(db.from('brokerage_branches').delete().eq('id',btn.dataset.deleteBranch));await route()}catch(err){toast(message(err))}})}

async function communityIndex(epoch){const rows=await result(db.from('listings').select('id,title,city,district,community_name,transaction_type,market_category,monthly_rent,asking_price,price_unit,area_ping,property_type',{count:'exact'}).eq('status','published').order('community_name',{ascending:true}).limit(1000));if(epoch!==routeEpoch)return;const groups=new Map;for(const p of rows||[]){const name=String(p.community_name||'').trim();if(!name)continue;const city=p.city||'',district=p.district||'',key=`${city}|${district}|${name}`;if(!groups.has(key))groups.set(key,{name,city,district,count:0,items:[]});const g=groups.get(key);g.count++;if(g.items.length<3)g.items.push(p)}const href=g=>`#/community/${encodeURIComponent(`${g.city}|${g.district}|${g.name}`)}`;app.innerHTML=`<section class="page-head"><p class="eyebrow">COMMUNITY DISCOVERY</p><h1>社區找房</h1><p>依刊登者填寫的社區名稱整理公開房源；房價與特色以各筆刊登資料為準。</p></section>${groups.size?`<div class="community-grid">${[...groups.values()].map(g=>`<article class="panel community-card"><p class="eyebrow">${esc(g.city)}${esc(g.district)}</p><h2><a href="${href(g)}">${esc(g.name)}</a></h2><p>${g.count} 筆公開房源</p><div>${g.items.map(p=>`<a class="link" href="#/listing/${p.id}" target="_blank" rel="noopener">${esc(p.title)} · ${marketPrice(p)}</a>`).join('<br>')}</div><a class="button" href="${href(g)}">查看社區房源</a></article>`).join('')}</div>`:'<div class="empty"><h2>目前尚無社區房源</h2><p>有公開房源填寫社區名稱後，這裡就會自動整理顯示。</p><a class="button" href="#/rent">回找房</a></div>'}`}
async function communityPage(rawName,epoch){let slug;try{slug=decodeURIComponent(rawName)}catch{slug=rawName}const [city,district,...rest]=slug.split('|'),name=rest.join('|');let q=db.from('listings').select(fields,{count:'exact'}).eq('status','published').eq('community_name',name).order('created_at',{ascending:false}).limit(100);if(city)q=q.eq('city',city);if(district)q=q.eq('district',district);const rows=await result(q);if(epoch!==routeEpoch)return;const photos=await signedPhotos(rows||[]);if(epoch!==routeEpoch)return;const topics=city&&district?await result(db.from('community_posts').select('id,category,title,body,created_at').eq('city',city).eq('district',district).eq('community_name',name).is('parent_id',null).eq('status','published').order('created_at',{ascending:false}).limit(50)):[];if(epoch!==routeEpoch)return;const replies=topics.length?await result(db.from('community_posts').select('id,parent_id,body,created_at').in('parent_id',topics.map(x=>x.id)).eq('status','published').order('created_at',{ascending:true}).limit(250)):[];const cats={discussion:'社區交流',question:'找房問答',experience:'入住經驗',safety:'安全提醒'};app.innerHTML=`<section class="page-head"><p class="eyebrow">COMMUNITY DISCOVERY</p><h1>${esc(name)}</h1><p>${esc(city)}${esc(district)} · ${photos.length} 筆公開刊登房源。地址、租售條件與社區資料請以刊登內容和實際現況確認。</p><a class="button" href="#/communities">所有社區</a></section><section class="community-board"><div class="results-head"><div><p class="eyebrow">NEIGHBOURHOOD BOARD</p><h2>社區討論與找房問答</h2></div></div><p class="muted">分享生活經驗、詢問看屋問題或提醒鄰里安全。請勿公開電話、門牌、身分資料或未經證實的指控。</p>${user?`<form id="community-post-form" class="panel community-post-form"><label>討論類型<select name="category">${Object.entries(cats).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>主題<input name="title" maxlength="120" minlength="4" required placeholder="例如：大樓隔音與管理費狀況"></label><label>內容<textarea name="body" maxlength="5000" minlength="4" rows="4" required></textarea></label><button class="button primary">發布討論</button></form>`:'<p><a class="button" href="#/account">登入後參與社區討論</a></p>'}${topics.length?topics.map(t=>{const rs=replies.filter(r=>r.parent_id===t.id);return `<article class="panel community-topic"><span class="tag">${cats[t.category]||'社區交流'}</span><h3>${esc(t.title)}</h3><p class="pre-wrap">${esc(t.body)}</p><small>社區會員 · ${new Date(t.created_at).toLocaleString('zh-TW')}</small><button class="link" data-community-report="${t.id}">檢舉</button>${rs.map(r=>`<div class="community-reply"><p class="pre-wrap">${esc(r.body)}</p><small>社區會員 · ${new Date(r.created_at).toLocaleString('zh-TW')}</small>${user?`<button class="link" data-community-report="${r.id}">檢舉</button>`:''}</div>`).join('')}${user?`<form class="community-reply-form" data-reply-topic="${t.id}"><label>回覆<input name="body" maxlength="2000" minlength="4" required placeholder="分享你的看法"></label><button class="button small">回覆</button></form>`:''}</article>`}).join(''):'<div class="empty"><p>還沒有討論，歡迎成為第一位分享者。</p></div>'}</section><section class="admin-section community-market-section"><div class="results-head"><div><p class="eyebrow">LISTINGS IN THIS COMMUNITY</p><h2>社區公開房源</h2></div><span>${photos.length} 筆近期刊登</span></div><div class="community-market-summary" id="community-market-summary"></div><form id="community-listing-filters" class="community-listing-filters"><label>交易方式<select name="transaction"><option value="all">租屋／出售／頂讓</option><option value="rent">出租</option><option value="sale">出售</option><option value="business_transfer">店面頂讓</option><option value="wanted_rent">求租需求</option><option value="wanted_buy">求購需求</option></select></label><label>物件類型<select name="category"><option value="all">全部類型</option>${Object.entries({residential:'住宅',new_development:'新建案',land:'土地',shop:'店面',office:'辦公／住辦',industrial:'廠房',parking:'車位'}).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>價格下限<input name="min" type="number" min="0" placeholder="先選交易方式" disabled></label><label>價格上限<input name="max" type="number" min="0" placeholder="先選交易方式" disabled></label><label>排序<select name="sort"><option value="new">最新刊登</option><option value="low" disabled>價格由低到高（請先選交易方式）</option><option value="high" disabled>價格由高到低（請先選交易方式）</option></select></label><button class="button small primary">套用條件</button><button type="button" class="button small" id="community-filter-reset">清除</button><span class="community-price-hint">租金與售價單位不同；選擇單一交易方式後才能使用價格篩選與排序，求租／求購預算不會混入租金／售價概況。</span></form><div id="community-listing-count" class="muted" role="status" aria-live="polite"></div><div id="community-listings" class="cards"></div><div id="community-listing-pagination" class="paging"></div><p class="muted">房源清單依最近 100 筆公開刊登整理；價格概況以此清單已載入資料計算，非完整社區行情。</p></section>`;const communityFilter=$('#community-listing-filters'),communityListings=$('#community-listings'),communityCount=$('#community-listing-count'),communitySummary=$('#community-market-summary');if(communityFilter){const values={transaction:'all',category:'all',min:'',max:'',sort:'new'},pageSize=12;const pricesFor=kind=>photos.filter(x=>kind==='rent'?x.transaction_type==='rent':kind==='sale'?x.transaction_type==='sale':x.transaction_type==='business_transfer').map(x=>kind==='rent'?Number(x.monthly_rent):Number(x.asking_price)).filter(x=>Number.isFinite(x)&&x>0);const rentPrices=pricesFor('rent'),salePrices=pricesFor('sale'),transferPrices=pricesFor('business_transfer'),range=(items,rent=false)=>items.length?`${Math.min(...items).toLocaleString()}–${Math.max(...items).toLocaleString()} 元${rent?'／月':''}`:'尚無刊登價格';communitySummary.innerHTML=`<article><span>社區租屋</span><strong>${rentPrices.length} 筆</strong><small>${range(rentPrices,true)}</small></article><article><span>社區出售</span><strong>${salePrices.length} 筆</strong><small>${range(salePrices)}</small></article><article><span>店面頂讓</span><strong>${transferPrices.length} 筆</strong><small>${range(transferPrices)}</small></article>`;const field=name=>communityFilter.querySelector(`[name="${name}"]`),transaction=field('transaction'),category=field('category'),min=field('min'),max=field('max'),sort=field('sort'),updatePriceControls=()=>{const active=transaction.value!=='all';min.disabled=max.disabled=!active;min.placeholder=max.placeholder=active?(['rent','wanted_rent'].includes(transaction.value)?'元／月':'元'):'先選交易方式';for(const option of sort.querySelectorAll('option'))if(option.value!=='new')option.disabled=!active};let page=0;const drawCommunityListings=()=>{let found=photos.filter(x=>(values.transaction==='all'||x.transaction_type===values.transaction)&&(values.category==='all'||x.market_category===values.category));if(values.transaction!=='all'){const amount=x=>['rent','wanted_rent'].includes(values.transaction)?Number(x.monthly_rent):Number(x.asking_price);if(values.min)found=found.filter(x=>amount(x)>=Number(values.min));if(values.max)found=found.filter(x=>amount(x)<=Number(values.max))}if(values.sort==='low'||values.sort==='high'){const field=['rent','wanted_rent'].includes(values.transaction)?'monthly_rent':'asking_price';found.sort((a,b)=>((Number(a[field])||0)-(Number(b[field])||0))*(values.sort==='low'?1:-1))}else found.sort((a,b)=>String(b.created_at||'').localeCompare(String(a.created_at||'')));const pages=Math.max(1,Math.ceil(found.length/pageSize));page=Math.max(0,Math.min(page,pages-1));const shown=found.slice(page*pageSize,(page+1)*pageSize);communityCount.textContent=`符合 ${found.length} 筆 · 第 ${page+1}／${pages} 頁`;communityListings.innerHTML=shown.length?shown.map(card).join(''):'<div class="empty"><h2>找不到符合條件的社區房源</h2><p>調整租售方式、物件類型或價格範圍再試一次。</p></div>';const paging=$('#community-listing-pagination');paging.innerHTML=pages>1?`<button type="button" class="button small" id="community-listings-prev" ${page===0?'disabled':''}>上一頁</button> <span>第 ${page+1}／${pages} 頁</span> <button type="button" class="button small" id="community-listings-next" ${page+1>=pages?'disabled':''}>下一頁</button>`:'';$('#community-listings-prev')?.addEventListener('click',()=>{page--;drawCommunityListings()});$('#community-listings-next')?.addEventListener('click',()=>{page++;drawCommunityListings()})};transaction.addEventListener('change',()=>{updatePriceControls();if(transaction.value==='all'){min.value='';max.value='';sort.value='new'}});communityFilter.onsubmit=e=>{e.preventDefault();values.transaction=transaction.value;values.category=category.value;values.min=min.value;values.max=max.value;values.sort=sort.value;if(values.min&&values.max&&Number(values.min)>Number(values.max)){toast('價格下限不可高於上限');return}page=0;drawCommunityListings()};$('#community-filter-reset').onclick=()=>{transaction.value='all';category.value='all';sort.value='new';min.value=max.value='';values.transaction='all';values.category='all';values.min=values.max='';values.sort='new';page=0;updatePriceControls();drawCommunityListings()};updatePriceControls();drawCommunityListings()}const postForm=$('#community-post-form');if(postForm)postForm.onsubmit=async e=>{e.preventDefault();if(!user)return;const f=e.currentTarget,b=f.querySelector('button');b.disabled=true;try{await result(db.from('community_posts').insert({city,district,community_name:name,author_id:user.id,category:f.querySelector('[name=category]').value,title:f.elements.title.value.trim(),body:f.querySelector('[name=body]').value.trim()}));toast('討論已發布');await communityPage(rawName,routeEpoch)}catch(err){toast(message(err));b.disabled=false}};app.querySelectorAll('[data-reply-topic]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,b=f.querySelector('button');b.disabled=true;try{await result(db.from('community_posts').insert({city,district,community_name:name,author_id:user.id,parent_id:f.dataset.replyTopic,category:'discussion',title:'回覆',body:f.querySelector('[name=body]').value.trim()}));toast('回覆已發布');await communityPage(rawName,routeEpoch)}catch(err){toast(message(err));b.disabled=false}});app.querySelectorAll('[data-community-report]').forEach(b=>b.onclick=async()=>{if(!user){location.hash='#/account';return}modal('檢舉社區內容',`<form id="community-report-form"><label class="modal-label">原因<select name="category"><option value="spam">垃圾訊息</option><option value="harassment">騷擾或仇恨</option><option value="fraud">疑似詐騙</option><option value="privacy">洩漏隱私</option><option value="other">其他</option></select></label><label class="modal-label">補充說明<textarea name="details" maxlength="1000"></textarea></label><button class="button primary">送出檢舉</button></form>`);$('#community-report-form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;try{await result(db.from('community_post_reports').insert({post_id:b.dataset.communityReport,reporter_id:user.id,category:f.querySelector('[name=category]').value,details:f.elements.details.value.trim()}));$('#info').close();toast('已送出檢舉，管理員會進行審查')}catch(err){toast(message(err))}}});}
