async function remindersPage(epoch){if(!requireUser())return;const rows=await result(db.from('favorites').select('listing_id,folder,note,pipeline_status,remind_at,listing:listings!inner(id,title,city,district,transaction_type,market_category,monthly_rent,asking_price,price_unit,area_ping,property_type,status)').eq('user_id',user.id).not('remind_at','is',null).eq('listing.status','published').order('remind_at',{ascending:true}).limit(200));if(epoch!==routeEpoch)return;const items=(rows||[]).filter(x=>x.listing&&x.remind_at),now=Date.now(),todayEnd=new Date();todayEnd.setHours(23,59,59,999);const due=items.filter(x=>Date.parse(x.remind_at)<=todayEnd.getTime()).length;const reminderCard=item=>{const listing=item.listing,delta=Date.parse(item.remind_at)-now,state=delta<0?'<span class="reminder-state overdue">已逾期</span>':Date.parse(item.remind_at)<=todayEnd.getTime()?'<span class="reminder-state today">今天要處理</span>':'<span class="reminder-state upcoming">即將提醒</span>',when=new Date(item.remind_at).toLocaleString('zh-TW',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});return `<article class="reminder-card"><div class="reminder-card-main"><div class="reminder-card-heading">${state}<span class="tag">${esc(item.folder||'未分類')}</span><span class="tag">${esc(favoriteStages[item.pipeline_status]||'收藏中')}</span></div><h2><a href="#/listing/${esc(listing.id)}" target="_blank" rel="noopener">${esc(listing.title)}</a></h2><p class="muted">${esc(listing.city||'')}${esc(listing.district||'')} · ${esc(categoryLabel(listing.market_category))}／${esc(transactionLabel(listing.transaction_type))} · ${marketPrice(listing)}</p><p><strong>提醒時間：</strong>${esc(when)}</p>${item.note?`<p class="reminder-private-note"><strong>私人備註：</strong>${esc(item.note)}</p>`:''}</div><div class="reminder-actions"><a class="button small" href="#/listing/${esc(listing.id)}" target="_blank" rel="noopener">查看房源</a><button class="button small primary" type="button" data-reminder-clear="${esc(item.listing_id)}">完成提醒</button><button class="button small" type="button" data-reminder-snooze="${esc(item.listing_id)}" data-days="1">延後 1 天</button><button class="button small" type="button" data-reminder-snooze="${esc(item.listing_id)}" data-days="7">延後 7 天</button></div></article>`};app.innerHTML=`<div class="breadcrumb"><a href="#/saved">我的收藏</a> ／ 看屋提醒</div><section class="intro"><div><div class="eyebrow">YOUR VIEWING REMINDERS</div><h1>看屋提醒</h1><p>集中查看你為租屋、買屋、土地與商用物件設定的提醒；可開啟房源、完成提醒或延後處理。</p></div><a class="button" href="#/saved">管理收藏與提醒</a></section><section class="reminder-summary"><article class="panel"><span>未完成提醒</span><strong>${items.length}</strong></article><article class="panel"><span>已到期／今天</span><strong>${due}</strong></article></section><p class="muted reminder-disclaimer">提醒會顯示在好居的提醒清單中；目前不會自動寄送 Email 或推播。</p><section class="reminder-list">${items.length?items.map(reminderCard).join(''):'<div class="empty"><h2>目前沒有待處理的看屋提醒</h2><p>在收藏房源中設定提醒時間，之後可回到這裡處理。</p><a class="button primary" href="#/saved">前往我的收藏</a></div>'}</section>`;const updateReminder=async(button,id,patch,success)=>{button.disabled=true;try{const changed=await result(db.from('favorites').update(patch).eq('user_id',user.id).eq('listing_id',id).not('remind_at','is',null).select('listing_id'));if(!changed.length)throw Error('提醒已變更或已移除，請重新整理');toast(success);await route()}catch(error){toast(message(error));button.disabled=false}};app.querySelectorAll('[data-reminder-clear]').forEach(button=>button.onclick=()=>updateReminder(button,button.dataset.reminderClear,{remind_at:null},'提醒已完成'));app.querySelectorAll('[data-reminder-snooze]').forEach(button=>button.onclick=()=>{const next=new Date();next.setDate(next.getDate()+Number(button.dataset.days));updateReminder(button,button.dataset.reminderSnooze,{remind_at:next.toISOString()},`提醒已延後 ${button.dataset.days} 天`)})}
async function comparePage(epoch){if(!compareSet.size){app.innerHTML='<div class="empty"><h2>先加入要比較的物件</h2><a class="button" href="#/rent">回到找房</a></div>';return}const rows=await result(db.from('listings').select(fields).in('id',[...compareSet]).eq('status','published'));if(epoch!==routeEpoch)return;const liveIds=new Set((rows||[]).map(p=>p.id));if([...compareSet].some(id=>!liveIds.has(id))){compareSet=new Set([...compareSet].filter(id=>liveIds.has(id)));persistCompareSet()}if(!compareSet.size){app.innerHTML='<div class="empty"><h2>比較清單中的房源已下架或無法查看</h2><a class="button" href="#/home">回到找房</a></div>';return}const items=await signedPhotos(rows);app.innerHTML=`<div class="breadcrumb"><a href="#/${marketView()}">找房</a> ／ 物件比較</div><section class="intro"><div><div class="eyebrow">COMPARE PROPERTIES</div><h1>比較物件</h1><p>並列價格、空間規格、費用及市場專屬資訊；最多比較三筆。租金、出售總價、頂讓總價與需求預算會標示各自口徑，請勿跨口徑直接比價。</p></div></section><div class="compare-table-wrap"><table class="compare-table"><thead><tr><th>比較項目</th>${items.map(p=>`<th><a href="#/listing/${p.id}" target="_blank" rel="noopener">${esc(p.title)}</a><button class="link" data-compare-remove="${p.id}">移除</button></th>`).join('')}</tr></thead><tbody>${compareRows().map(([label,value])=>`<tr><th>${label}</th>${items.map(p=>`<td>${esc(value(p))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;document.querySelectorAll('[data-compare-remove]').forEach(b=>b.onclick=()=>{compareSet.delete(b.dataset.compareRemove);persistCompareSet();route()})}

async function mapPage(epoch){const view=marketViews[marketView()];activeMarket=marketView();const response=await searchQuery(false).range(0,99);if(response.error)throw response.error;const rows=await signedPhotos(response.data||[]);if(epoch!==routeEpoch)return;const located=rows.filter(p=>Number.isFinite(Number(p.latitude))&&Number.isFinite(Number(p.longitude))&&p.latitude!==null&&p.longitude!==null);app.innerHTML=`<div class="breadcrumb"><a href="#/${activeMarket}">${view.label}</a> ／ 地圖找房</div><section class="intro"><div><div class="eyebrow">MAP SEARCH</div><h1>${view.label}地圖找房</h1><p>地圖顯示刊登者提供的約略位置。最多顯示 100 筆符合條件的物件。</p></div><a class="button" href="#/${activeMarket}">返回列表</a></section><div class="map-poi-controls"><label>附近設施<select id="map-poi-category">${Object.entries(nearbyTypes).map(([key,v])=>`<option value="${key}">${v.label}</option>`).join('')}</select></label><label>搜尋半徑<select id="map-poi-radius"><option value="500">500 公尺</option><option value="1000" selected>1 公里</option><option value="2000">2 公里</option></select></label><button class="button small" id="map-poi-search">在地圖中心搜尋設施</button><span id="map-poi-status" role="status" aria-live="polite">先縮放到街區再查詢周邊設施。</span></div><p class="map-poi-note">使用此功能會將地圖中心的約略座標、設施類別與搜尋半徑送往 OpenStreetMap 公開查詢服務；不會傳送帳號或聯絡資料。資料為社群維護，可能不完整或非即時。</p><div class="map-search-layout"><div id="property-map" role="application" aria-label="房源與附近設施地圖"></div><section><h2>地圖範圍房源 <span id="map-count" class="muted">${located.length} 個地圖標記／${rows.length} 筆</span></h2><div class="map-radius-search"><label>地圖中心半徑<select id="map-radius"><option value="500">500 公尺</option><option value="1000" selected>1 公里</option><option value="2000">2 公里</option><option value="5000">5 公里</option></select></label><button class="button small primary" id="search-map-radius">搜尋中心附近房源</button><button class="button small" id="search-map-area">搜尋目前地圖範圍</button></div><div id="map-cards" class="cards">${rows.map(card).join('')||'<div class="empty"><h2>目前沒有符合條件的物件</h2></div>'}</div></section></div><p class="map-attribution-note">地圖 © <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap 貢獻者</a>。標記位置由刊登者提供，請勿視為精確地址。</p>${rows.length>0&&located.length===0?'<p class="notice">目前這些物件沒有提供約略座標，因此只會顯示在下方清單。刊登者可在刊登表單新增地圖座標。</p>':''}`;if(!window.L){$('#property-map').innerHTML='<div class="empty">地圖元件載入失敗，請重新整理頁面。</div>';return}const map=window.L.map('property-map',{scrollWheelZoom:false}).setView([23.7,120.9],7);window.L.tileLayer((cfg&&cfg.mapTileUrl)||'https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'}).addTo(map);let markers=[],poiMarkers=[];const drawMarkers=(items,fit=false)=>{markers.forEach(marker=>map.removeLayer?.(marker));markers=[];for(const p of items.filter(x=>Number.isFinite(Number(x.latitude))&&Number.isFinite(Number(x.longitude))&&x.latitude!==null&&x.longitude!==null)){const marker=window.L.marker([Number(p.latitude),Number(p.longitude)]).addTo(map);marker.bindPopup(`<a href="#/listing/${p.id}" target="_blank" rel="noopener">${esc(p.title)}</a><br>${marketPrice(p)}<br>${esc(p.city)}${esc(p.district)}`);markers.push(marker)}if(fit&&markers.length){const group=window.L.featureGroup(markers);map.fitBounds(group.getBounds().pad(0.16),{maxZoom:14})}};drawMarkers(rows,true);$('#map-poi-search').onclick=async e=>{const button=e.currentTarget,status=$('#map-poi-status'),kind=$('#map-poi-category').value,meters=Number($('#map-poi-radius').value),spec=nearbyTypes[kind],center=map.getCenter();if(map.getZoom()<12){status.textContent='請先放大到街區（地圖縮放 12 級以上），再查詢附近設施。';return}button.disabled=true;status.textContent='正在查詢 OpenStreetMap 附近設施…';try{const key=`haoju:map-poi:v1:${center.lat.toFixed(4)}:${center.lng.toFixed(4)}:${kind}:${meters}`;let cached=null;try{cached=JSON.parse(localStorage.getItem(key)||'null')}catch(_){}let elements;if(cached&&cached.saved>Date.now()-86400000&&Array.isArray(cached.elements))elements=cached.elements;else{const selectors=spec.filters.map(f=>`nwr(around:${meters},${center.lat},${center.lng})[${f}];`).join(''),query=`[out:json][timeout:20];(${selectors});out center 100;`,controller=new AbortController(),timer=setTimeout(()=>controller.abort(),22000);let response;try{response=await fetch('https://overpass-api.de/api/interpreter',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:'data='+encodeURIComponent(query),signal:controller.signal})}finally{clearTimeout(timer)}if(!response.ok)throw Error(`周邊資料服務暫時無法使用（${response.status}），請稍後再試。`);const body=await response.json();elements=Array.isArray(body.elements)?body.elements:[];try{localStorage.setItem(key,JSON.stringify({saved:Date.now(),elements}))}catch(_){}}if(epoch!==routeEpoch)return;poiMarkers.forEach(marker=>map.removeLayer?.(marker));poiMarkers=[];const found=elements.map(x=>{const lat=x.lat??x.center?.lat,lng=x.lon??x.center?.lon,t=x.tags||{};return{lat:Number(lat),lng:Number(lng),name:t.name||t.brand||t.operator||spec.label+'設施',type:t.amenity||t.shop||t.leisure||t.railway||t.highway||spec.label}}).filter(x=>Number.isFinite(x.lat)&&Number.isFinite(x.lng)).slice(0,80);for(const x of found){const marker=window.L.marker([x.lat,x.lng]).addTo(map);marker.bindPopup(`<strong>${esc(x.name)}</strong><br>${esc(x.type)}・${spec.label}<br><a href="https://www.openstreetmap.org/?mlat=${x.lat}&mlon=${x.lng}#map=17/${x.lat}/${x.lng}" target="_blank" rel="noopener noreferrer">在 OpenStreetMap 查看 ↗</a>`);poiMarkers.push(marker)}status.textContent=found.length?`找到 ${found.length} 個${spec.label}設施（顯示最多 80 筆；資料可能不完整）。`:`搜尋範圍內沒有找到已登錄的${spec.label}設施。`}catch(err){if(epoch===routeEpoch){const why=err.name==='AbortError'?'周邊查詢逾時。':message(err);status.textContent=`${why}${poiMarkers.length?'已保留上次成功顯示的圖釘。':''}`;addRetryControl(status,button.onclick)}}finally{button.disabled=false}};$('#search-map-area').onclick=async e=>{const button=e.currentTarget,status=$('#map-count'),bounds=map.getBounds(),sw=bounds.getSouthWest(),ne=bounds.getNorthEast();button.disabled=true;status.textContent='正在查詢目前範圍…';try{const found=await result(searchQuery(false).gte('latitude',sw.lat).lte('latitude',ne.lat).gte('longitude',sw.lng).lte('longitude',ne.lng).range(0,99));const current=await signedPhotos(found||[]);if(epoch!==routeEpoch)return;$('#map-cards').innerHTML=current.length?current.map(card).join(''):'<div class="empty"><h2>此範圍沒有房源</h2><p>拖曳或縮放地圖後再搜尋。</p></div>';status.textContent=`${current.length} 筆符合目前地圖範圍`;drawMarkers(current)}catch(err){status.textContent=message(err)}finally{button.disabled=false}};$('#search-map-radius').onclick=async e=>{const button=e.currentTarget,status=$('#map-count'),center=map.getCenter(),meters=Number($('#map-radius').value),dLat=meters/111320,dLng=meters/(111320*Math.max(.15,Math.cos(center.lat*Math.PI/180)));button.disabled=true;status.textContent=`正在搜尋中心 ${meters>=1000?`${meters/1000} 公里`:`${meters} 公尺`}內房源…`;try{const candidates=await result(searchQuery(false).gte('latitude',center.lat-dLat).lte('latitude',center.lat+dLat).gte('longitude',center.lng-dLng).lte('longitude',center.lng+dLng).range(0,499));const distance=(p)=>{const rad=x=>x*Math.PI/180,lat1=rad(center.lat),lat2=rad(Number(p.latitude)),dphi=rad(Number(p.latitude)-center.lat),dlambda=rad(Number(p.longitude)-center.lng),a=Math.sin(dphi/2)**2+Math.cos(lat1)*Math.cos(lat2)*Math.sin(dlambda/2)**2;return 6371000*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))};const matches=(candidates||[]).filter(p=>p.latitude!==null&&p.longitude!==null&&Number.isFinite(Number(p.latitude))&&Number.isFinite(Number(p.longitude))&&distance(p)<=meters);const current=await signedPhotos(matches);if(epoch!==routeEpoch)return;$('#map-cards').innerHTML=current.length?current.map(card).join(''):'<div class="empty"><h2>指定半徑內沒有房源</h2><p>可調大搜尋半徑或移動地圖中心後再搜尋。</p></div>';status.textContent=`地圖中心 ${meters>=1000?`${meters/1000} 公里`:`${meters} 公尺`}內找到 ${current.length} 筆房源${(candidates||[]).length===500?'（最多檢查 500 筆，結果可能受限）':''}`;drawMarkers(current)}catch(err){status.textContent=message(err)}finally{button.disabled=false}}}
async function calendarPage(epoch){if(!requireUser())return;const start=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth(),1),end=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+1,1);const rows=await result(db.from('viewing_requests').select('id,listing_id,requester_id,owner_id,requested_at,status,listing:listings(title,city,district)').or(`requester_id.eq.${user.id},owner_id.eq.${user.id}`).in('status',['pending','accepted']).gte('requested_at',start.toISOString()).lt('requested_at',end.toISOString()).order('requested_at',{ascending:true}).limit(300));if(epoch!==routeEpoch)return;const events=new Map;for(const r of rows){if(!r.requested_at)continue;const dt=new Date(r.requested_at),day=dt.getDate();if(!events.has(day))events.set(day,[]);events.get(day).push(r)}const offset=start.getDay(),days=new Date(start.getFullYear(),start.getMonth()+1,0).getDate(),cells=Array.from({length:offset+days},(_,i)=>{if(i<offset)return '<div class="calendar-day muted-day" aria-hidden="true"></div>';const day=i-offset+1,items=events.get(day)||[];return `<div class="calendar-day"><strong>${day}</strong>${items.map(r=>`<a class="calendar-event ${r.status==='accepted'?'accepted':''}" href="#/inquiry/${r.id}"><time>${new Date(r.requested_at).toLocaleTimeString('zh-TW',{hour:'2-digit',minute:'2-digit'})}</time> ${esc(r.listing?.title||'房屋詢問')}<small>${requestStatuses[r.status]||r.status} · ${r.requester_id===user.id?'我提出':'收到'}</small></a>`).join('')}</div>`}).join('');app.innerHTML=`<section class="intro"><div><div class="eyebrow">VIEWING CALENDAR</div><h1>看屋行事曆</h1><p>整理本月已提出時間的看屋與洽談；開啟事件可回到詢問對話確認。</p></div></section><div class="calendar-toolbar"><button class="button" id="calendar-prev" aria-label="上個月">‹</button><h2>${start.toLocaleDateString('zh-TW',{year:'numeric',month:'long'})}</h2><button class="button" id="calendar-next" aria-label="下個月">›</button><a class="button" href="#/inquiries">所有詢問</a></div><div class="calendar-grid">${['日','一','二','三','四','五','六'].map(x=>`<div class="calendar-weekday">週${x}</div>`).join('')}${cells}</div>${rows.length?`<p class="muted">本月共有 ${rows.length} 筆預約時段；包含尚待屋主確認的時間。</p>`:'<div class="empty"><h2>本月尚無預約時段</h2><p>收到或提出看屋時間後，會在此整理顯示。</p></div>'}`;$('#calendar-prev').onclick=()=>{calendarMonth=new Date(start.getFullYear(),start.getMonth()-1,1);route()};$('#calendar-next').onclick=()=>{calendarMonth=new Date(start.getFullYear(),start.getMonth()+1,1);route()}}
function visitorToken(){try{let token=localStorage.getItem('haoju-visitor-id');if(!token){token=crypto.randomUUID();localStorage.setItem('haoju-visitor-id',token)}return token}catch{return crypto.randomUUID()}}
function recordListingView(id){try{const visitor=visitorToken();if(user){db.rpc('haoju_record_listing_view',{p_listing_id:id,p_visitor_id:visitor}).then(({error})=>{if(error)console.warn('Listing view was not recorded',error.message)});db.rpc('haoju_record_member_listing_view',{p_listing_id:id}).then(({error})=>{if(error)console.warn('Member browsing history was not recorded',error.message)})}}catch(err){console.warn('Listing view was not recorded',err)}}
async function notificationsPage(epoch){if(!requireUser())return;const rows=await result(db.from('haoju_notifications').select('id,listing_id,request_id,rental_agreement_id,brokerage_claim_id,title,body,read_at,created_at').eq('user_id',user.id).order('created_at',{ascending:false}).limit(100));if(epoch!==routeEpoch)return;const category=n=>n.request_id?'conversation':n.rental_agreement_id?'rental':n.brokerage_claim_id?'account':/搜尋|上架|符合/i.test(n.title)?'search':/降價|價格|交易|提案/i.test(n.title+' '+n.body)?'market':'other',labels={all:'全部',unread:'未讀',conversation:'詢問與預約',rental:'租賃條件',market:'價格與交易',search:'搜尋房源',account:'帳號與審核',other:'其他'};const unread=rows.filter(n=>!n.read_at).length;app.innerHTML=`<section class="intro"><div><div class="eyebrow">YOUR NOTIFICATIONS</div><h1>通知</h1><p>追蹤新房源、詢問訊息、預約更新、收藏物件降價與交易進度。${unread?`目前有 ${unread} 則未讀。`:'目前沒有未讀通知。'}</p></div><div class="manage-actions">${unread?'<button class="button primary" id="mark-all-read">全部標記已讀</button>':''}</div></section><section class="panel notification-toolbar"><label>通知類型<select id="notification-filter">${Object.entries(labels).map(([k,v])=>`<option value="${k}">${v}${k==='unread'?`（${unread}）`:''}</option>`).join('')}</select></label><span class="muted" id="notification-count-label">顯示 ${rows.length} 則通知</span></section><div id="notification-list">${rows.length?rows.map(n=>`<article class="manage-card notification-card ${n.read_at?'read':''}" data-notification-category="${category(n)}" data-notification-read="${n.read_at?'yes':'no'}"><div><span class="tag">${n.read_at?'已讀':'未讀'} · ${labels[category(n)]}</span><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><small>${new Date(n.created_at).toLocaleString('zh-TW')}</small>${n.request_id?`<p><a class="link" href="#/inquiry/${n.request_id}">開啟詢問對話 →</a></p>`:n.rental_agreement_id?`<p><a class="link" href="#/rental-agreement/id/${n.rental_agreement_id}">查看租賃條件 →</a></p>`:n.brokerage_claim_id?`<p><a class="link" href="#/brokerage-claims">查看品牌認領申請 →</a></p>`:n.listing_id?`<p><a class="link" href="#/listing/${n.listing_id}" target="_blank" rel="noopener">查看房源 →</a></p>`:''}</div>${n.read_at?'':`<button class="button small" data-mark-read="${n.id}">標記已讀</button>`}</article>`).join(''):'<div class="empty"><h2>目前沒有通知</h2><p>符合已存搜尋的新房源上架或收藏物件降價時，我們會在這裡通知你。</p><a class="button" href="#/rent">繼續找房</a></div>'}</div>`;const apply=()=>{const key=$('#notification-filter').value,cards=[...app.querySelectorAll('[data-notification-category]')];let count=0;for(const card of cards){const show=key==='all'||(key==='unread'?card.dataset.notificationRead==='no':card.dataset.notificationCategory===key);card.hidden=!show;if(show)count++}$('#notification-count-label').textContent=`顯示 ${count} 則通知`};$('#notification-filter').onchange=apply;app.querySelectorAll('[data-mark-read]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await result(db.from('haoju_notifications').update({read_at:new Date().toISOString()}).eq('id',b.dataset.markRead).eq('user_id',user.id));await refreshUnreadNotifications();await route()}catch(err){toast(message(err));b.disabled=false}});if($('#mark-all-read'))$('#mark-all-read').onclick=async e=>{const b=e.currentTarget;b.disabled=true;try{await result(db.from('haoju_notifications').update({read_at:new Date().toISOString()}).eq('user_id',user.id).is('read_at',null));await refreshUnreadNotifications();await route()}catch(err){toast(message(err));b.disabled=false}}}
const nearbyTypes={transit:{label:'交通',filters:['railway=station','station=subway','public_transport=station','highway=bus_stop']},education:{label:'學校',filters:['amenity=school','amenity=kindergarten','amenity=college','amenity=university']},shopping:{label:'採買',filters:['shop=supermarket','shop=convenience','amenity=marketplace']},health:{label:'醫療',filters:['amenity=hospital','amenity=clinic','amenity=doctors','amenity=pharmacy']},parks:{label:'公園',filters:['leisure=park','leisure=playground']}};
function nearestTransitSection(p){const has=Number.isFinite(Number(p.latitude))&&Number.isFinite(Number(p.longitude))&&p.latitude!==null&&p.longitude!==null;return `<section class="detail-section nearest-transit-section"><h2>附近大眾運輸站</h2><p class="muted">依刊登者提供的約略房源座標與政府開放站點座標計算直線距離，不代表步行距離或實際出入口；請以現場與地圖確認。</p>${has?'<div id="nearest-transit-status" class="muted" role="status" aria-live="polite">正在整理附近站點…</div><ol id="nearest-transit-results" class="nearest-transit-list"></ol>':'<p class="notice">刊登者尚未提供約略座標，無法計算最近站點。</p>'}${transitStationAttribution()}</section>`}
async function wireNearestTransit(p,epoch){const status=$('#nearest-transit-status'),list=$('#nearest-transit-results');if(!status||!list)return;const stations=await loadTransitStations();if(epoch!==routeEpoch)return;const rad=x=>x*Math.PI/180,lat=Number(p.latitude),lng=Number(p.longitude),dist=(s)=>{const dLat=rad(s.lat-lat),dLng=rad(s.lng-lng),a=Math.sin(dLat/2)**2+Math.cos(rad(lat))*Math.cos(rad(s.lat))*Math.sin(dLng/2)**2;return 6371000*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))},nearest=stations.map(s=>({...s,distance:dist(s)})).sort((a,b)=>a.distance-b.distance).slice(0,5);if(!nearest.length){status.textContent='目前沒有可用的政府站點座標。';return}status.textContent=`列出最近 ${nearest.length} 個站點；站點座標來源與授權見上方說明。`;list.innerHTML=nearest.map(s=>`<li><div><strong>${esc(s.name)}站</strong><small>${esc([s.system,s.route,s.city].filter(Boolean).join(' · '))}</small></div><span>${s.distance<1000?`${Math.round(s.distance)} 公尺`:`${(s.distance/1000).toFixed(1)} 公里`}</span><a href="https://www.openstreetmap.org/?mlat=${s.lat}&mlon=${s.lng}#map=17/${s.lat}/${s.lng}" target="_blank" rel="noopener noreferrer">地圖 ↗</a></li>`).join('')}
function nearbyFacilitiesSection(p){const has=Number.isFinite(Number(p.latitude))&&Number.isFinite(Number(p.longitude))&&p.latitude!==null&&p.longitude!==null;return `<section class="detail-section nearby-section"><h2>附近生活設施</h2><p class="muted">以房源約略位置搜尋周邊交通、學校、採買、醫療或公園。資料由 OpenStreetMap 貢獻者整理，可能不完整；請自行確認實際距離與營業狀態。</p>${has?`<div class="nearby-controls"><label>設施類別<select id="nearby-category">${Object.entries(nearbyTypes).map(([key,v])=>`<option value="${key}">${v.label}</option>`).join('')}</select></label><label>搜尋半徑<select id="nearby-radius"><option value="500">500 公尺</option><option value="1000" selected>1 公里</option><option value="2000">2 公里</option></select></label><button id="nearby-search" class="button primary">查詢附近設施</button></div><p class="nearby-privacy muted">按下查詢後，會將約略座標、類別與半徑送往 OpenStreetMap 公開查詢服務；不會傳送聯絡方式或帳號資料。</p><div id="nearby-status" role="status" aria-live="polite">選好類別與半徑後，查詢附近設施。</div><div id="nearby-results"></div>`:'<p class="notice">刊登者尚未提供地圖約略座標，因此無法搜尋周邊設施。請以地址自行確認周邊環境。</p>'}<p class="map-attribution-note">設施資料 © <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener noreferrer">OpenStreetMap 貢獻者</a></p></section>`}
function addRetryControl(status,run,label='重新查詢'){const retry=document.createElement('button');retry.type='button';retry.className='button small nearby-retry';retry.textContent=label;retry.onclick=run;status.append(' ',retry)}
function wireNearbyFacilities(p,epoch){const button=$('#nearby-search'),category=$('#nearby-category'),radius=$('#nearby-radius'),status=$('#nearby-status'),results=$('#nearby-results');if(!button)return;const cacheKey=(kind,meters)=>`haoju:nearby:v1:${Number(p.latitude).toFixed(5)}:${Number(p.longitude).toFixed(5)}:${kind}:${meters}`;const run=async()=>{const kind=category.value,meters=Number(radius.value),spec=nearbyTypes[kind];button.disabled=true;status.textContent='正在查詢 OpenStreetMap 周邊設施…';try{const key=cacheKey(kind,meters);let cached=null;try{cached=JSON.parse(localStorage.getItem(key)||'null')}catch(_){}let elements;if(cached&&cached.saved>Date.now()-86400000&&Array.isArray(cached.elements))elements=cached.elements;else{const selectors=spec.filters.map(f=>`nwr(around:${meters},${Number(p.latitude)},${Number(p.longitude)})[${f}];`).join('');const query=`[out:json][timeout:20];(${selectors});out center 80;`;const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),22000);let response;try{response=await fetch('https://overpass-api.de/api/interpreter',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:'data='+encodeURIComponent(query),signal:controller.signal})}finally{clearTimeout(timer)}if(!response.ok)throw Error(`周邊資料服務暫時無法使用（${response.status}），請稍後再試。`);const body=await response.json();elements=Array.isArray(body.elements)?body.elements:[];try{localStorage.setItem(key,JSON.stringify({saved:Date.now(),elements}))}catch(_){}}if(epoch!==routeEpoch)return;const distance=(lat,lng)=>{const r=6371000,toRad=x=>x*Math.PI/180,dl=toRad(lat-Number(p.latitude)),dn=toRad(lng-Number(p.longitude)),a=Math.sin(dl/2)**2+Math.cos(toRad(Number(p.latitude)))*Math.cos(toRad(lat))*Math.sin(dn/2)**2;return 2*r*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))};const rows=elements.map(x=>{const lat=x.lat??x.center?.lat,lng=x.lon??x.center?.lon,t=x.tags||{};return{lat:Number(lat),lng:Number(lng),title:t.name||t.brand||t.operator||spec.label+'設施',type:t.amenity||t.shop||t.leisure||t.railway||t.highway||'',dist:distance(Number(lat),Number(lng))}}).filter(x=>Number.isFinite(x.lat)&&Number.isFinite(x.lng)&&x.dist<=meters).sort((a,b)=>a.dist-b.dist).slice(0,30);status.textContent=rows.length?`找到 ${rows.length} 個${spec.label}設施${elements.length>rows.length?'（最多顯示最近 30 筆）':''}。`:`${meters>=1000?meters/1000+' 公里':meters+' 公尺'}內沒有找到已登錄的${spec.label}設施。`;results.innerHTML=rows.length?`<ul class="nearby-list">${rows.map(x=>`<li><div><strong>${esc(x.title)}</strong><small>${esc(x.type)}</small></div><span>${Math.round(x.dist)} 公尺</span><a href="https://www.openstreetmap.org/?mlat=${x.lat}&mlon=${x.lng}#map=17/${x.lat}/${x.lng}" target="_blank" rel="noopener noreferrer">地圖 ↗</a></li>`).join('')}</ul>`:''}catch(err){if(epoch!==routeEpoch)return;const why=err.name==='AbortError'?'周邊查詢逾時。':message(err);status.textContent=`${why}${results.innerHTML?'已保留先前成功的設施清單。':''}`;addRetryControl(status,run)}finally{button.disabled=false}};button.onclick=run}
function projectKey(p){if(!String(p.community_name||'').trim())return JSON.stringify({id:p.id});return JSON.stringify({city:p.city||'',district:p.district||'',developer:p.developer_name||'',name:String(p.community_name).trim()})}
function projectHref(p){return `#/project/${encodeURIComponent(projectKey(p))}`}
function projectComparisonMarkup(selected){if(!selected.length)return '';const rows=[['縣市／行政區',g=>`${g.city}${g.district}`],['建商',g=>g.developer||'未提供'],['銷售階段',g=>g.status],['預計交屋',g=>g.handover||'未提供'],['建案總戶數',g=>g.unitCount?`${g.unitCount} 戶`:'未提供'],['公開刊登戶別',g=>`${g.count} 個`],['公開戶別開價',g=>g.minPrice?(g.minPrice===g.maxPrice?`${g.minPrice.toLocaleString()} 元`:`${g.minPrice.toLocaleString()}–${g.maxPrice.toLocaleString()} 元`):'洽詢']];return `<section class="project-compare-panel"><div class="results-head"><h2>建案比較 <span class="muted">${selected.length}／3</span></h2><button type="button" class="button small" id="project-compare-clear">清空比較</button></div><div class="project-compare-scroll"><table><thead><tr><th>比較項目</th>${selected.map(g=>`<th>${esc(g.name)}<button type="button" class="link" data-project-remove="${encodeURIComponent(g.key)}">移除</button></th>`).join('')}</tr></thead><tbody>${rows.map(([label,value])=>`<tr><th>${label}</th>${selected.map(g=>`<td>${esc(value(g))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="muted">資料依公開刊登彙整；實際價格、戶數與銷售狀態請向建商／代銷確認。</p></section>`}
async function projectIndex(epoch){const raw=await result(db.from('listings').select('id,title,city,district,market_category,asking_price,community_name,developer_name,project_status,handover_date,project_unit_count,updated_at').eq('status','published').eq('market_category','new_development').order('updated_at',{ascending:false}).limit(1000));if(epoch!==routeEpoch)return;const rows=await signedPhotos(raw||[]);if(epoch!==routeEpoch)return;const groups=new Map;for(const p of rows){const name=String(p.community_name||'').trim(),key=name?projectKey(p):JSON.stringify({id:p.id});if(!groups.has(key))groups.set(key,{key,name:name||p.title,city:p.city||'',district:p.district||'',developer:p.developer_name||'',statuses:new Set,dates:[],prices:[],unitCount:null,listings:[],photo:''});const g=groups.get(key);if(p.project_status)g.statuses.add(p.project_status);if(p.handover_date)g.dates.push(p.handover_date);if(Number(p.asking_price)>0)g.prices.push(Number(p.asking_price));if(p.project_unit_count)g.unitCount=Math.max(g.unitCount||0,Number(p.project_unit_count));if(g.listings.length<100)g.listings.push(p)}const projects=[...groups.values()].map(g=>({...g,count:g.listings.length,status:[...g.statuses].join('、')||'狀態未提供',handover:g.dates.sort()[0]||'',minPrice:g.prices.length?Math.min(...g.prices):null,maxPrice:g.prices.length?Math.max(...g.prices):null}));let query='',stage='',sort='recent',page=0;const size=12;app.innerHTML=`<div class="breadcrumb"><a href="#/new">新建案</a> ／ 建案專區</div><section class="intro"><div><div class="eyebrow">NEW DEVELOPMENT PROJECTS</div><h1>新建案專區</h1><p>先看建案，再比較各戶別開價、坪數、格局與交屋時間。建案資料由刊登者提供。</p></div><a class="button" href="#/new">查看全部新建案房源</a></section><form id="project-search" class="project-search"><input name="q" placeholder="搜尋建案名稱、建商或縣市" aria-label="搜尋建案" maxlength="120"><select name="stage" aria-label="建案銷售階段"><option value="">所有銷售階段</option>${['規劃中','預售中','興建中','即將完工','已完工','銷售中','完銷'].map(x=>`<option>${x}</option>`).join('')}</select><select name="sort" aria-label="排序建案"><option value="recent">最新刊登</option><option value="handover">交屋日期</option><option value="units">戶數較多</option></select><button class="button primary">搜尋建案</button></form><div id="project-index-results" aria-live="polite"></div><div id="project-comparison"></div><p class="muted">最多整理最新 1,000 筆公開新建案房源；相同縣市、行政區、建商與建案名稱會合併顯示。</p>`;const draw=()=>{let found=projects.filter(g=>`${g.name} ${g.developer} ${g.city} ${g.district}`.toLowerCase().includes(query)&&(!stage||g.statuses.has(stage)));found.sort(sort==='handover'?(a,b)=>(a.handover||'9999').localeCompare(b.handover||'9999'):sort==='units'?(a,b)=>(b.unitCount||0)-(a.unitCount||0):(a,b)=>(b.listings[0].updated_at||'').localeCompare(a.listings[0].updated_at||''));const pages=Math.max(1,Math.ceil(found.length/size));page=Math.min(page,pages-1);const visible=found.slice(page*size,(page+1)*size);$('#project-index-results').innerHTML=visible.length?`<div class="project-grid">${visible.map(g=>`<article class="project-card"><a class="project-card-image" href="#/project/${encodeURIComponent(g.key)}">${g.photo?`<img src="${esc(g.photo)}" alt="${esc(g.name)}建案照片">`:'<span>新建案</span>'}</a><div class="project-card-body"><p class="eyebrow">${esc(g.city)}${esc(g.district)} · ${esc(g.status)}</p><h2><a href="#/project/${encodeURIComponent(g.key)}">${esc(g.name)}</a></h2><p>${esc(g.developer||'建商資料未提供')}</p><p class="project-meta">${g.count} 個刊登戶別${g.unitCount?` · 建案 ${g.unitCount} 戶`:''}${g.handover?` · 預計交屋 ${esc(g.handover)}`:''}</p><strong>${g.minPrice?g.minPrice===g.maxPrice?`${g.minPrice.toLocaleString()} 元`:`${g.minPrice.toLocaleString()}–${g.maxPrice.toLocaleString()} 元`:'價格洽詢'}</strong><button type="button" class="link project-compare-toggle" data-project-compare="${encodeURIComponent(g.key)}">${projectCompareSet.has(g.key)?'✓ 已加入建案比較':'＋ 加入建案比較'}</button></div></article>`).join('')}</div><div class="project-paging"><button class="button small" id="project-prev" ${page===0?'disabled':''}>上一頁</button><span>第 ${page+1}／${pages} 頁 · ${found.length} 個建案</span><button class="button small" id="project-next" ${page+1>=pages?'disabled':''}>下一頁</button></div>`:'<div class="empty"><h2>目前找不到符合條件的建案</h2><p>可清除篩選，或瀏覽全部新建案房源。</p><a class="button" href="#/new">查看新建案</a></div>';const selected=projects.filter(g=>projectCompareSet.has(g.key));$('#project-comparison').innerHTML=projectComparisonMarkup(selected);$('#project-index-results').querySelectorAll('[data-project-compare]').forEach(button=>button.onclick=()=>{const key=decodeURIComponent(button.dataset.projectCompare);if(projectCompareSet.has(key))projectCompareSet.delete(key);else if(projectCompareSet.size<3)projectCompareSet.add(key);else toast('一次最多比較三個建案');draw()});$('#project-comparison').querySelectorAll('[data-project-remove]').forEach(button=>button.onclick=()=>{projectCompareSet.delete(decodeURIComponent(button.dataset.projectRemove));draw()});$('#project-compare-clear')?.addEventListener('click',()=>{projectCompareSet.clear();draw()});$('#project-prev')?.addEventListener('click',()=>{page--;draw()});$('#project-next')?.addEventListener('click',()=>{page++;draw()})};$('#project-search').onsubmit=e=>{e.preventDefault();const v=Object.fromEntries(new FormData(e.target));query=(v.q||'').trim().toLowerCase();stage=v.stage||'';sort=v.sort||'recent';page=0;draw()};draw()}
