function parseDevelopmentUnitCsv(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){cell+='"';i++}else if(c==='"')quoted=false;else cell+=c}else if(c==='"'){if(cell)return{error:'CSV 引號位置錯誤。'};quoted=true}else if(c===','){row.push(cell);cell=''}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(v=>v.trim()))rows.push(row);row=[];cell=''}else cell+=c}if(quoted)return{error:'CSV 有未關閉的引號。'};row.push(cell);if(row.some(v=>v.trim()))rows.push(row);if(rows.length<2)return{error:'CSV 至少要有標題列和一筆戶別資料。'};const required=['unit_name','floor_label','layout','area_ping','price_min','price_max','availability','handover_date','note'],headers=rows[0].map(x=>x.trim()),indexes=required.map(k=>headers.indexOf(k));if(indexes.some(i=>i<0))return{error:`CSV 標題需包含：${required.join(', ')}`};const data=rows.slice(1).map((r,i)=>Object.fromEntries(required.map((k,j)=>[k,(r[indexes[j]]||'').trim()])));if(data.some(r=>r.unit_name.length===0||!/^\d+(\.\d{1,2})?$/.test(r.area_ping)||!['','available','reserved','sold','not_released'].includes(r.availability)||r.price_min&&!/^\d+$/.test(r.price_min)||r.price_max&&!/^\d+$/.test(r.price_max)||r.handover_date&&!/^\d{4}-\d{2}-\d{2}$/.test(r.handover_date)))return{error:'CSV 有空白戶別名稱，或坪數、價格、銷售狀態、日期格式不正確。'};const names=data.map(r=>r.unit_name);if(new Set(names).size!==names.length)return{error:'CSV 內含重複戶別名稱，請先修正。'};if(data.length>500)return{error:'單次最多匯入 500 筆，請將檔案拆成多批。'};return{rows:data}}

