function viewingChecklistFor(p){if(p.transaction_type==='wanted_rent')return [['budget','確認可負擔月租、押金及搬遷初期支出'],['area','整理優先區域、通勤路線及可接受交通時間'],['move','確認預計入住日、租期與看屋時段'],['household','整理入住人數、寵物、開伙及其他必要條件'],['eligibility','確認報稅、租屋補助、入籍等需求是否必要'],['documents','準備看屋時要確認的身分與租約問題'],['contact','確認聯絡方式、回覆時段及防詐查證步驟']];if(p.transaction_type==='wanted_buy')return [['budget','確認總價上限、頭期款、貸款與稅費預算'],['area','整理優先區域、通勤路線及生活機能'],['property','列出必要的物件類型、坪數、格局及屋況條件'],['timeline','確認購屋時程、貸款預審與付款準備'],['tradeoff','區分必要條件、可妥協條件與優先順序'],['documents','準備洽談時要查驗的權利、費用與交易流程問題'],['contact','確認聯絡方式、回覆時段及防詐查證步驟']];const category=viewingChecklistTemplates[p.market_category]||viewingChecklistTemplates.residential;const common=[['identity','核對刊登者身分及其出租／出售權限'],['price','確認刊登價格、付款方式與所有額外費用'],['condition','把現況、瑕疵、修繕責任及交付日期記錄清楚']];const transaction=['rent'].includes(p.transaction_type)?[['deposit','確認押金、租期、租金包含項目及退租條件'],['lease','確認書面租約、報稅／補助／入籍等條件']]:p.transaction_type==='sale'?[['title','確認權狀、持分、抵押、查封及交易流程'],['tax','詢問稅費、仲介費、交屋款與點交條件']]:[['terms','確認頂讓條件、費用構成與書面約定']];return [...category,...common,...transaction]}
function viewingChecklistStorageKey(id){return `haoju_viewing_checklist_v1_${String(id).replace(/[^a-zA-Z0-9-]/g,'')}`}
async function viewingChecklistPage(id,epoch){const row=await result(db.from('listings').select('id,title,city,district,street,transaction_type,market_category,property_type,monthly_rent,asking_price,price_unit,community_name,status').eq('id',id).maybeSingle());if(epoch!==routeEpoch)return;if(!row){app.innerHTML='<div class="empty"><h2>找不到這筆房源，或目前無權查看</h2><a class="button" href="#/home">返回找房</a></div>';return}const items=viewingChecklistFor(row),key=viewingChecklistStorageKey(id);let savedState={checked:{},note:''};try{savedState={...savedState,...JSON.parse(localStorage.getItem(key)||'{}')}}catch{}const label=categoryLabel(row.market_category),price=['rent','wanted_rent'].includes(row.transaction_type)?`${Number(row.monthly_rent||0).toLocaleString()} 元／月`:row.asking_price?`${Number(row.asking_price).toLocaleString()} 元${row.price_unit==='per_ping'?'／坪':''}`:'面議';app.innerHTML=`<div class="breadcrumb"><a href="#/listing/${row.id}" target="_blank" rel="noopener">返回房源</a> ／ 看屋／現勘清單</div><section class="viewing-checklist-page"><header class="viewing-checklist-head"><div><p class="eyebrow">PROPERTY VISIT CHECKLIST</p><h1>${['wanted_rent','wanted_buy'].includes(row.transaction_type)?'需求確認清單':'看屋／現勘檢查清單'}</h1><h2>${esc(row.title)}</h2><p>${esc([row.city,row.district,row.street].filter(Boolean).join(''))} · ${esc(label)}／${esc(transactionLabel(row.transaction_type))} · ${price}</p><small>房源資訊由刊登者提供，請以現場查驗和正式文件為準。</small></div><div class="viewing-checklist-controls"><button class="button primary" id="checklist-print" type="button">列印／存成 PDF</button><button class="button" id="checklist-reset" type="button">清除此裝置的勾選</button><a class="button" href="#/listing/${row.id}" target="_blank" rel="noopener">返回房源</a></div></header><div class="viewing-checklist-progress"><strong id="checklist-progress">0 / ${items.length} 項已確認</strong><span><i id="checklist-progress-bar"></i></span></div><section class="viewing-checklist-items"><h2>現場檢查項目</h2>${items.map(([key,label])=>`<label class="viewing-check-item"><input type="checkbox" data-check-item="${key}" ${savedState.checked?.[key]?'checked':''}><span>${esc(label)}</span></label>`).join('')}</section><section class="viewing-checklist-notes"><h2>現場備註</h2><label for="checklist-note">記錄待追問事項、照片編號或檢查結果</label><textarea id="checklist-note" rows="5" maxlength="3000" placeholder="請勿在共用裝置記錄敏感個人資料">${esc(savedState.note||'')}</textarea></section><p class="viewing-checklist-local-note">勾選與備註僅儲存在此瀏覽器，不會同步到帳號或送到好居伺服器；清除瀏覽器資料也會一併刪除。本清單是個人提醒，不取代專業查驗、權利調查或正式契約。</p></section>`;const checks=[...app.querySelectorAll('[data-check-item]')],progress=()=>{const done=checks.filter(x=>x.checked).length;$('#checklist-progress').textContent=`${done} / ${items.length} 項已確認`;$('#checklist-progress-bar').style.width=`${items.length?done/items.length*100:0}%`};const persist=()=>{try{const checked=Object.fromEntries(checks.map(x=>[x.dataset.checkItem,x.checked]));localStorage.setItem(key,JSON.stringify({checked,note:$('#checklist-note').value,updatedAt:new Date().toISOString()}));return true}catch{return false}};checks.forEach(x=>x.addEventListener('change',()=>{progress();if(!persist())toast('瀏覽器儲存空間無法使用，請確認設定。')}));$('#checklist-note').addEventListener('input',()=>{if(!persist())toast('備註未能儲存，請確認瀏覽器設定。')});$('#checklist-print').onclick=()=>window.print();$('#checklist-reset').onclick=()=>{if(!confirm('要清除此房源在本裝置儲存的勾選和備註嗎？'))return;localStorage.removeItem(key);checks.forEach(x=>x.checked=false);$('#checklist-note').value='';progress()};progress()}
async function sharePublicListing(p){const url=new URL(`#/listing/${encodeURIComponent(p.id)}`,cfg.siteUrl).href,payload={title:p.title,text:`${p.city||''}${p.district||''} · ${transactionLabel(p.transaction_type)} · 好居 HAŌJU`,url};if(p.status!=='published'){toast('只有已公開房源可以分享');return}try{if(typeof navigator!=='undefined'&&typeof navigator.share==='function'){await navigator.share(payload);return}if(typeof navigator!=='undefined'&&navigator.clipboard?.writeText){await navigator.clipboard.writeText(url);toast('房源連結已複製');return}}catch(err){if(err?.name==='AbortError')return;try{if(typeof navigator!=='undefined'&&navigator.clipboard?.writeText){await navigator.clipboard.writeText(url);toast('房源連結已複製');return}}catch{}}modal('分享房源',`<p>複製以下連結分享此公開房源：</p><label class="modal-label">房源連結<input id="share-listing-url" type="url" readonly value="${esc(url)}" aria-label="房源分享連結"></label><p class="muted">分享連結只包含公開房源頁面，不會包含你的私人收藏或聯絡資料。</p>`);const field=$('#share-listing-url');field?.focus?.();field?.select?.()}
async function detail(id,epoch){const row=await result(db.from('listings').select(fields).eq('id',id).maybeSingle());if(epoch!==routeEpoch)return;if(!row){app.innerHTML='<div class="empty"><h2>房源不存在、已下架或尚未公開</h2><a class="button" href="#/">回到找房</a></div>';return}const [p]=await signedPhotos([row]);const [agent,priceHistory]=await Promise.all([result(db.from('agent_profiles').select('id,display_name,is_verified').eq('id',row.agent_profile_id||'00000000-0000-0000-0000-000000000000').maybeSingle()),result(db.from('listing_price_history').select('price_label,old_price,new_price,price_unit,changed_at').eq('listing_id',id).order('changed_at',{ascending:false}).limit(20))]);if(epoch!==routeEpoch)return;if(p.status==='published')recordListingView(p.id);app.innerHTML=`<div class="breadcrumb"><a href="#/${activeMarket}">${marketViews[activeMarket].label}</a> ／ ${esc(p.city)} ／ ${esc(p.district)}</div><div class="detail-top"><div><h1>${esc(p.title)}${p.owner_verified?' <span class="verified-badge">已驗證刊登者</span>':''}${isFeatured(p)?' <span class="featured-badge">好居精選</span>':''}</h1><p class="location detail-address-line">${esc(p.city+p.district+p.street)}${p.station?`・${esc(p.station)}`:''}</p><div class="detail-meta-line"><span>好居案件編號 ${esc(p.id.slice(0,8).toUpperCase())}</span><span>${p.updated_at?`更新於 ${new Date(p.updated_at).toLocaleDateString('zh-TW')}`:''}</span></div></div><div class="detail-actions"><button class="button" data-fav="${p.id}" aria-label="收藏房源" aria-pressed="${saved.has(p.id)}">${saved.has(p.id)?'♥':'♡'}</button>${p.status==='published'?'<button class="button" id="share-listing" type="button">分享房源</button>':''}</div></div>${p.status!=='published'?`<p class="notice">${statuses[p.status]}：此頁僅供你預覽，尚未公開。</p>`:''}<div class="detail-grid"><div><div class="gallery">${p.photos.filter(x=>x.url).length?`<div class="photo-gallery"><img id="hero-photo" class="detail-image" src="${esc(p.photos.find(x=>x.url).url)}" alt="${esc(p.photos.find(x=>x.url).alt_text||p.title)}">${p.photos.filter(x=>x.url).length>1?`<div class="photo-thumbs">${p.photos.filter(x=>x.url).map((x,i)=>`<button type="button" class="photo-thumb ${i===0?'active':''}" data-photo-index="${i}" aria-label="查看第 ${i+1} 張照片"><img src="${esc(x.url)}" alt=""></button>`).join('')}</div>`:''}</div>`:'<div class="detail-image no-photo">尚未提供照片</div>'}</div><section class="detail-section"><h2>物件規格</h2><div class="facts"><div>${Number(p.area_ping)} 坪<small>刊登坪數</small></div><div>${esc(p.bedrooms==null?'未提供':p.bedrooms===0?'開放格局':`${p.bedrooms} 房`)}<small>房間數</small></div><div>${esc(p.floor_label||'未提供')}<small>樓層</small></div><div>${esc(p.building_type||p.property_type)}<small>房屋型態</small></div></div>${propertySpecs(p)}${rentalPostingSpecs(p)}</section>${p.videoUrl||p.video_url?`<section class="detail-section"><h2>房屋影片</h2>${p.videoUrl?`<video controls preload="metadata" class="listing-video" src="${esc(p.videoUrl)}"></video>`:`<a class="button" href="${esc(p.video_url)}" target="_blank" rel="noopener noreferrer">開啟房屋影片 ↗</a>`}</section>`:''}<section class="detail-section"><h2>物件介紹</h2><p class="pre-wrap">${esc(p.description||'刊登者尚未填寫介紹。')}</p></section><section class="detail-section"><h2>物件特色與費用</h2><div class="tags">${[...(p.amenities||[]),...(p.included_fees||[]).map(x=>`含${x}`),...(p.business_transfer_includes||[])].map(t=>`<span class="tag">${esc(t)}</span>`).join('')||'未提供'}</div></section>${p.market_category==='new_development'?`<section class="detail-section"><h2>建案資訊</h2><p>建商／代銷：${esc(p.developer_name||'未提供')}</p><p>銷售狀態：${esc(p.project_status||'未提供')}・戶數：${p.project_unit_count||'未提供'}・預計交屋：${esc(p.handover_date||'未提供')}</p><a class="button small" href="${projectHref(p)}">查看建案專頁與其他戶別 →</a></section>`:''}${p.market_category==='land'?`<section class="detail-section"><h2>土地資料</h2><p>土地類型：${esc(p.land_type||'未提供')}・使用分區：${esc(p.zoning||'未提供')}・臨路：${p.frontage_width||'未提供'} 公尺・道路寬：${p.land_road_width_m??'未提供'} 公尺・深度：${p.land_depth||'未提供'} 公尺</p><p>地勢／形狀：${esc(p.land_terrain||'未提供')}／${esc(p.land_shape||'未提供')}・坡度：${p.land_slope_percent==null?'未提供':`${p.land_slope_percent}%`}・道路出入：${esc(landAccessLabel(p.land_access))}</p><p>水電／公共設施：${esc((p.land_utilities||[]).join('、')||'未提供')}</p><p class="muted">資料由刊登者提供，建築可行性及道路權利請自行向主管機關與專業人員確認。</p></section>`:''}${['shop','office','industrial','parking'].includes(p.market_category)?`<section class="detail-section"><h2>商用空間資料</h2><p>業種／類別：${esc(p.business_category||'未提供')}・使用分區：${esc(p.zoning||'未提供')}</p><p>管理費：${p.monthly_management_fee==null?'未提供':`${Number(p.monthly_management_fee).toLocaleString()} 元／月`}・車位：${p.parking_spaces??'未提供'}</p>${p.market_category==='parking'?`<p>車位型式：${esc(p.parking_type||'未提供')}・適用車種：${esc(p.parking_vehicle_limit||'未提供')}・室內／地下：${p.parking_indoor==null?'未提供':p.parking_indoor?'是':'否'}・電動車充電：${p.parking_ev_charging==null?'未提供':p.parking_ev_charging?'有':'無'}</p>`:''}${p.commercial_min_lease_months||p.commercial_deposit_months!=null?`<p>最短租期：${p.commercial_min_lease_months?`${p.commercial_min_lease_months} 個月`:'未提供'}・押金：${p.commercial_deposit_months==null?'未提供':`${p.commercial_deposit_months} 個月`}</p>`:''}${p.market_category==='industrial'?`<p>室內淨高：${p.warehouse_clear_height_m==null?'未提供':`${p.warehouse_clear_height_m} 公尺`}・電力：${p.warehouse_power_kw==null?'未提供':`${p.warehouse_power_kw} kW`}・貨車碼頭：${p.warehouse_loading_dock==null?'未提供':p.warehouse_loading_dock?'有':'無'}</p>`:''}</section>`:''}</div><aside><div class="contact-box"><span class="muted">${['rent','wanted_rent'].includes(p.transaction_type)?(p.transaction_type==='rent'?'每月租金':'每月求租預算'):p.transaction_type==='wanted_buy'?'求購總價預算':p.transaction_type==='business_transfer'?'頂讓開價':'物件開價'}</span><div class="price">${marketPrice(p)}</div><a class="map-link" target="_blank" rel="noopener noreferrer" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(`${p.city}${p.district}${p.street}${p.station?' ' + p.station:''}`)}">在地圖查看附近位置 ↗</a><p class="muted">實際地址請由刊登者確認；地圖僅供參考。</p><hr>${p.is_auction?`<section class="auction-notice"><h3>法院拍賣資料</h3><p>${esc(p.auction_court)} · ${esc(p.auction_case_number)}</p><p>第 ${Number(p.auction_round)||1} 拍 · ${p.auction_date?new Date(p.auction_date).toLocaleString('zh-TW'):'未提供時間'}</p>${p.auction_deposit!=null?`<p>投標保證金：${Number(p.auction_deposit).toLocaleString()} 元</p>`:''}${/^https:\/\//i.test(p.auction_notice_url||'')?`<a class="button" href="${esc(p.auction_notice_url)}" target="_blank" rel="noopener noreferrer">開啟法院公告</a>`:''}<p class="notice">請以法院公告為準，確認拍賣日期、保證金、點交狀態與投標資格；切勿向刊登者或陌生帳戶預先匯款。</p></section>`:''}<h3>${esc(p.advertiser_type)}刊登${p.brokerage_name?`・${esc(p.brokerage_name)}`:''}</h3>${agent?`<a class="button agent-detail-link" href="#/agent/${agent.id}">查看經紀人服務頁 · ${esc(agent.display_name)}${agent.is_verified?' ✓':''}</a>`:''}<a class="button" href="#/viewing-checklist/${p.id}">${['wanted_rent','wanted_buy'].includes(p.transaction_type)?'需求確認清單':'看屋／現勘檢查清單'}</a><button id="contact" class="button primary">${user?'查看聯絡方式':'登入查看聯絡方式'}</button>${user&&p.owner_id!==user.id&&p.transaction_type==='rent'?'<button id="apply-rental" class="button primary">申請租屋</button>':''}${user&&p.owner_id!==user.id&&['sale','business_transfer','wanted_buy','wanted_rent'].includes(p.transaction_type)?'<button id="make-offer" class="button primary">提出價格／條件</button>':''}${user&&p.owner_id!==user.id?'<button id="request-viewing" class="button">詢問／預約洽談</button>':''}<button id="report-listing" class="button report-button">檢舉此房源</button>${user&&p.owner_id===user.id&&p.status==='published'&&!isFeatured(p)?'<button id="promote-listing" class="button">申請好居精選</button>':''}<p class="notice">請實際查驗物件，核對刊登者身分並確認交易條件。</p></div></aside></div>${p.status==='published'?`<section class="detail-section price-history"><h2>價格變動紀錄</h2>${priceHistory.length?`<ol>${priceHistory.map(e=>`<li><span>${new Date(e.changed_at).toLocaleString('zh-TW')}</span><strong class="${Number(e.new_price)<Number(e.old_price)?'price-down':'price-up'}">${Number(e.new_price)<Number(e.old_price)?'降價':'調價'}</strong><span>${esc(e.price_label)}：${Number(e.old_price).toLocaleString()} → ${Number(e.new_price).toLocaleString()} 元${e.price_unit==='per_ping'?'／坪':''}</span></li>`).join('')}</ol>`:'<p class="muted">此房源尚無公開價格調整紀錄。</p>'}<a class="link" href="#/price-drops">查看近期降價房源 →</a></section>`:''}${nearestTransitSection(p)}${nearbyFacilitiesSection(p)}`;await wireNearestTransit(p,epoch);if(Number.isFinite(Number(p.latitude))&&Number.isFinite(Number(p.longitude))){wireNearbyFacilities(p,epoch)}$('#share-listing')?.addEventListener('click',()=>sharePublicListing(p));$('#apply-rental')?.addEventListener('click',()=>requestRentalApplication(p));$('#make-offer')?.addEventListener('click',()=>requestTransactionOffer(p));$('#request-viewing')?.addEventListener('click',()=>requestViewing(p));$('#report-listing').onclick=()=>reportListing(p);$('#promote-listing')?.addEventListener('click',()=>requestPromotion(p));document.querySelectorAll('[data-photo-index]').forEach(button=>button.onclick=()=>{const x=p.photos.filter(x=>x.url)[Number(button.dataset.photoIndex)];$('#hero-photo').src=x.url;$('#hero-photo').alt=x.alt_text||p.title;document.querySelectorAll('.photo-thumb').forEach(b=>b.classList.toggle('active',b===button))});$('#contact').onclick=async e=>{if(!user){location.hash='#/account';return}const button=e.currentTarget;button.disabled=true;try{const c=await result(db.from('listing_contacts').select('contact_name,phone,line_id').eq('listing_id',id).maybeSingle());modal('聯絡刊登者',c?`<p>聯絡人：${esc(c.contact_name)}</p><p>電話：${esc(c.phone||'未提供')}</p><p>LINE ID：${esc(c.line_id||'未提供')}</p>`:'<p>刊登者尚未提供聯絡方式。</p>')}catch(e){toast(message(e))}finally{button.disabled=false}}}
function toDateTimeLocal(value){if(!value)return '';const date=new Date(value);return new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16)}
function inputField(name,label,value='',options=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" value="${esc(value)}" ${options}></div>`}
function selectField(name,label,values,value){return `<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}">${values.map(item=>{const v=Array.isArray(item)?item[0]:item,l=Array.isArray(item)?item[1]:item;return `<option value="${esc(v)}" ${v===value?'selected':''}>${esc(l)}</option>`}).join('')}</select></div>`}
function lockForm(form,locked){form.querySelectorAll('button,input,select,textarea').forEach(x=>x.disabled=locked)}
async function refreshAdmin(){isAdmin=false;if(!user||!db?.rpc)return;try{isAdmin=(await result(db.rpc('haoju_is_admin')))===true}catch(_){isAdmin=false}header()}

const rentalAgreementStatuses={draft:'草稿',proposed:'等待租客確認',tenant_confirmed:'等待屋主定稿',confirmed:'雙方已確認',revision_requested:'租客要求修改',cancelled:'流程已取消'};
async function rentalAgreementPage(mode,id,epoch){if(!requireUser())return;let agreement,application;if(mode==='id'){agreement=await result(db.from('rental_agreements').select('*').eq('id',id).maybeSingle());if(agreement)application=await result(db.from('rental_applications').select('id,status,tenant_id,owner_id,applicant_name,move_in_date,lease_months,listing:listings(title,city,district)').eq('id',agreement.application_id).maybeSingle())}else{application=await result(db.from('rental_applications').select('id,status,tenant_id,owner_id,applicant_name,move_in_date,lease_months,listing:listings(title,city,district,monthly_rent)').eq('id',id).maybeSingle());if(application)agreement=await result(db.from('rental_agreements').select('*').eq('application_id',id).maybeSingle())}if(epoch!==routeEpoch)return;if(!application||!['tenant_id','owner_id'].some(k=>application[k]===user.id)){app.innerHTML='<div class="empty"><h2>找不到租屋申請</h2><a class="button" href="#/rental-applications">返回租屋申請</a></div>';return}if(application.status!=='approved'){app.innerHTML='<div class="empty"><h2>此申請尚未核准</h2><p>核准租屋申請後才能開始確認租賃條件。</p><a class="button" href="#/rental-applications">返回租屋申請</a></div>';return}const owner=application.owner_id===user.id;const status=agreement?.status||'draft';const title=application.listing?.title||'出租房源';const canEdit=owner&&(!agreement||['draft','revision_requested'].includes(status));const terms=agreement?`<div class="application-facts"><p><strong>月租：</strong>${Number(agreement.monthly_rent||0).toLocaleString()} 元</p><p><strong>租期：</strong>${esc(agreement.lease_start||'')} 至 ${esc(agreement.lease_end||'')}</p><p><strong>押金：</strong>${esc(agreement.deposit_months)} 個月</p><p><strong>水電與費用：</strong>${esc(agreement.utilities||'未填寫')}</p><p><strong>其他條件：</strong>${esc(agreement.other_terms||'未填寫')}</p></div>`:'';app.innerHTML=`<section class="intro"><div><div class="eyebrow">RENTAL TERMS</div><h1>租賃條件確認</h1><p>${esc(title)} · ${esc(application.listing?.city||'')}${esc(application.listing?.district||'')}。此流程記錄雙方提出及確認的條件，請另外簽署正式書面租約；平台確認不取代正式租約或法律程序。</p></div></section><article class="manage-card"><span class="tag">${esc(rentalAgreementStatuses[status]||status)}</span><h2>${esc(title)}</h2>${agreement?terms:`<p>${owner?'建立條件草稿後，提交給租客確認。':'等待房東建立租賃條件；建立後可在此檢視及回覆。'}</p>`}${agreement?.revision_note?`<p><strong>修改／取消說明：</strong>${esc(agreement.revision_note)}</p>`:''}${agreement?.owner_proposed_at?`<p>房東送出：${new Date(agreement.owner_proposed_at).toLocaleString('zh-TW')}</p>`:''}${agreement?.tenant_confirmed_at?`<p>租客確認：${new Date(agreement.tenant_confirmed_at).toLocaleString('zh-TW')}</p>`:''}${agreement?.owner_confirmed_at?`<p>房東定稿：${new Date(agreement.owner_confirmed_at).toLocaleString('zh-TW')}</p>`:''}${canEdit?`<form id="rental-agreement-form" class="editor-form"><label>月租金<input name="monthly_rent" type="number" min="1" max="1000000000" required value="${agreement?.monthly_rent??application.listing?.monthly_rent??''}"></label><label>租期開始<input name="lease_start" type="date" required value="${agreement?.lease_start||application.move_in_date||''}"></label><label>租期結束<input name="lease_end" type="date" required value="${agreement?.lease_end||''}"></label><label>押金（月）<input name="deposit_months" type="number" min="0" max="24" step="0.5" required value="${agreement?.deposit_months??2}"></label><label>水電、管理費等分攤<textarea name="utilities" maxlength="2000" rows="3">${esc(agreement?.utilities||'')}</textarea></label><label>其他條件<textarea name="other_terms" maxlength="3000" rows="4">${esc(agreement?.other_terms||'')}</textarea></label><button class="button primary">${status==='revision_requested'?'修改後重新送出':'送交租客確認'}</button></form>`:''}${owner&&status==='draft'&&agreement?`<p>草稿已建立，填妥條件後提交。</p>`:''}${!owner&&status==='draft'?'<p>等待房東送出條件。</p>':''}${!owner&&status==='proposed'?`<div class="application-actions"><button class="button primary" data-agreement-action="confirm_tenant">確認上述條件</button><button class="button" data-agreement-action="request_revision">提出修改</button></div>`:''}${owner&&status==='tenant_confirmed'?`<div class="application-actions"><button class="button primary" data-agreement-action="confirm_owner">確認並定稿</button></div>`:''}${agreement&&['draft','proposed','tenant_confirmed','revision_requested'].includes(status)?`<button class="button small" data-agreement-action="cancel">取消此流程</button>`:''}<p class="muted">平台僅記錄條件與操作時間；確認前請逐項核對，雙方仍應另行完成正式書面租約。</p><a class="button small" href="#/rental-applications">返回租屋申請</a></article>`;const form=$('#rental-agreement-form');if(form)form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button');b.disabled=true;try{const values=Object.fromEntries(new FormData(form));if(values.lease_end<=values.lease_start)throw Error('租期結束日需晚於開始日');let agreementId=agreement?.id;if(!agreementId)agreementId=await result(db.rpc('haoju_create_rental_agreement',{p_application_id:application.id}));await result(db.rpc('haoju_update_rental_agreement',{p_agreement_id:agreementId,p_action:status==='revision_requested'?'revise':'propose',p_monthly_rent:Number(values.monthly_rent),p_lease_start:values.lease_start,p_lease_end:values.lease_end,p_deposit_months:Number(values.deposit_months),p_utilities:values.utilities,p_other_terms:values.other_terms}));toast('租賃條件已送交租客確認');await route()}catch(err){toast(message(err));b.disabled=false}};app.querySelectorAll('[data-agreement-action]').forEach(b=>b.onclick=async()=>{const action=b.dataset.agreementAction;let revision='';if(action==='request_revision'||action==='cancel'){revision=prompt(action==='request_revision'?'請說明希望調整的條件（至少 5 個字）':'請填寫取消原因（可留白）',action==='cancel'?'雙方停止此協議流程':'')??null;if(revision===null)return}b.disabled=true;try{await result(db.rpc('haoju_update_rental_agreement',{p_agreement_id:agreement.id,p_action:action,p_revision_note:revision}));toast(action==='confirm_tenant'?'已確認租賃條件':'租賃條件流程已更新');await route()}catch(err){toast(message(err));b.disabled=false}})}
async function requestRentalApplication(p){if(!user){location.hash='#/account';return}if(p.transaction_type!=='rent'||p.status!=='published'||p.owner_id===user.id){toast('只有已上架且非本人刊登的出租物件可提出申請');return}const localToday=new Date(Date.now()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,10);modal('申請租屋',`<p>${esc(p.title)}・${esc(p.city)}${esc(p.district)}・月租 ${Number(p.monthly_rent||0).toLocaleString()} 元</p><p class="muted">申請資料只會提供給你和房東查看。收入為選填；請只填寫願意分享的資料。</p><form id="rental-application-form" class="rental-application-form"><label class="modal-label">申請人姓名<input name="applicant_name" required maxlength="100"></label><label class="modal-label">聯絡電話<input name="contact_phone" type="tel" required minlength="6" maxlength="30" autocomplete="tel"></label><label class="modal-label">工作／身份<select name="employment_type" required><option value="受雇">受雇</option><option value="自營／接案">自營／接案</option><option value="學生">學生</option><option value="退休">退休</option><option value="其他">其他</option></select></label><label class="modal-label">每月收入（選填）<input name="monthly_income" type="number" min="0" max="1000000000" step="1000" placeholder="可留白"></label><label class="modal-label">入住人數<input name="occupants" type="number" min="1" max="20" value="1" required></label><label class="modal-label">預計入住日<input name="move_in_date" type="date" min="${localToday}" required></label><label class="modal-label">預計租期（月）<input name="lease_months" type="number" min="1" max="120" value="12" required></label><label class="modal-label">是否有寵物<select name="has_pets"><option value="false">沒有</option><option value="true">有</option></select></label><label class="modal-label">是否吸菸<select name="smoker"><option value="false">否</option><option value="true">是</option></select></label><label class="modal-label">自我介紹／入住需求<textarea name="introduction" required maxlength="2000" rows="4" placeholder="簡單介紹入住成員與租屋需求"></textarea></label><label class="privacy-consent"><input type="checkbox" name="share_consent" required> 我同意將本申請資料提供給此房源刊登者審核。</label><button class="button primary">送出租屋申請</button></form>`);const form=$('#rental-application-form');form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button');b.disabled=true;try{const values=Object.fromEntries(new FormData(form));if(!form.querySelector('[name=share_consent]').checked)throw Error('請先同意將資料提供給刊登者');const moveDate=new Date(`${values.move_in_date}T00:00:00`);if(Number.isNaN(moveDate.getTime())||moveDate<new Date(new Date().toDateString()))throw Error('預計入住日不能早於今天');const lease=Number(values.lease_months);if(!Number.isInteger(lease)||lease<1||lease>120)throw Error('租期需介於 1 至 120 個月');const created=await result(db.from('rental_applications').insert({listing_id:p.id,tenant_id:user.id,owner_id:p.owner_id,applicant_name:String(values.applicant_name||'').trim(),contact_phone:String(values.contact_phone||'').trim(),employment_type:values.employment_type,monthly_income:values.monthly_income?Number(values.monthly_income):null,occupants:Number(values.occupants),move_in_date:values.move_in_date,lease_months:lease,has_pets:values.has_pets==='true',smoker:values.smoker==='true',introduction:String(values.introduction||'').trim()}).select('id').single());$('#info').close();toast('租屋申請已送出');location.hash='#/rental-applications';return created}catch(err){toast(message(err));b.disabled=false}}}
async function requestTransactionOffer(p){if(!user){location.hash='#/account';return}if(!['sale','business_transfer','wanted_buy','wanted_rent'].includes(p.transaction_type)||p.status!=='published'||p.owner_id===user.id){toast('此物件目前不能提出價格提案');return}const unit=['wanted_rent','rent'].includes(p.transaction_type)?'monthly':(p.price_unit==='per_ping'?'per_ping':'total'),unitText=unit==='monthly'?'元／月':unit==='per_ping'?'元／坪':'元';modal('提出價格／交易條件',`<p>${esc(p.title)}・${esc(p.city)}${esc(p.district)}</p><p class="muted">提案只會提供給你和刊登者查看，雙方可在此提出不同價格與條件。</p><form id="transaction-offer-form"><label class="modal-label">你的價格（${unitText}）<input name="proposed_price" type="number" min="1" max="100000000000" required></label><label class="modal-label">補充交易條件<textarea name="terms" maxlength="3000" rows="4" placeholder="例如交屋時間、設備或租期條件"></textarea></label><label class="modal-label">提案有效期限（選填）<input name="expires_at" type="date"></label><button class="button primary">送出提案</button></form>`);const form=$('#transaction-offer-form');form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button');b.disabled=true;try{const v=Object.fromEntries(new FormData(form)),price=Number(v.proposed_price);if(!Number.isSafeInteger(price)||price<1||price>100000000000)throw Error('請輸入有效價格');const expires=v.expires_at?new Date(`${v.expires_at}T23:59:59`).toISOString():null;if(expires&&new Date(expires)<=new Date())throw Error('有效期限必須晚於現在');await result(db.from('transaction_offers').insert({listing_id:p.id,proposer_id:user.id,owner_id:p.owner_id,proposed_price:price,price_unit:unit,terms:String(v.terms||'').trim(),expires_at:expires}).select('id').single());$('#info').close();toast('交易提案已送出');location.hash='#/offers'}catch(err){toast(message(err));b.disabled=false}}}
function transactionGuidance(p={}){if(p.transaction_type==='rent')return '租屋請由雙方核對身分、書面租約、押金與費用、屋況點交及入住日期，款項請依正式約定自行處理。';if(p.market_category==='land')return '土地請核對地籍與界址、使用分區、通行條件及現況；必要時向主管機關或專業人員確認。';if(p.market_category==='new_development')return '新建案請核對建商與銷售文件、戶別狀態、付款節點、預計交屋與交付標準。';if(p.market_category==='shop'||p.market_category==='office')return '商用空間請核對用途與登記條件、租期／押金、管理費、設備及點交範圍。';if(p.market_category==='industrial')return '廠房請核對用途許可、電力／淨高、裝卸條件、設備責任與環境相關要求。';if(p.market_category==='parking')return '車位請核對權利型態、車位尺寸與型式、適用車種、管理費及充電規則。';if(p.transaction_type==='business_transfer')return '頂讓請核對設備清冊、租約承接、營業用途、押金與頂讓範圍，並將約定寫入正式文件。';return '買賣請核對雙方身分與權利文件、總價與費用、書面契約、款項安排及交屋點交；需要時洽詢專業人員。'}
async function transactionsPage(epoch){if(!requireUser())return;const rows=await result(db.from('transaction_cases').select('id,accepted_offer_id,listing_id,proposer_id,owner_id,agreed_price,price_unit,agreed_terms,status,proposer_completed_at,owner_completed_at,cancellation_note,created_at,completed_at,listing:listings(title,city,district,transaction_type,market_category),milestones:transaction_milestones(id,milestone_key,title,proposer_completed_at,owner_completed_at)').or(`proposer_id.eq.${user.id},owner_id.eq.${user.id}`).order('updated_at',{ascending:false}).limit(200));if(epoch!==routeEpoch)return;const labels={pending:'待開始',in_progress:'進行中',completed:'雙方確認完成',cancelled:'已取消'},priceUnit=x=>x==='monthly'?'元／月':x==='per_ping'?'元／坪':'元';app.innerHTML=`<section class="intro"><div><div class="eyebrow">TRANSACTION PROGRESS</div><h1>交易進度</h1><p>雙方接受提案後，於此核對身分、物件、契約、款項與點交進度。平台不代簽契約或收取款項。</p></div></section>${rows.length?`<div class="transaction-list">${rows.map(c=>{const proposer=c.proposer_id===user.id,ownDone=proposer?c.proposer_completed_at:c.owner_completed_at,otherDone=proposer?c.owner_completed_at:c.proposer_completed_at,milestones=c.milestones||[],allDone=milestones.length>0&&milestones.every(m=>m.proposer_completed_at&&m.owner_completed_at),totalChecks=milestones.length*2,doneChecks=milestones.reduce((n,m)=>n+Number(Boolean(m.proposer_completed_at))+Number(Boolean(m.owner_completed_at)),0),progress=totalChecks?Math.round(doneChecks/totalChecks*100):0;return `<article class="transaction-card"><div class="transaction-heading"><div><span class="tag">${labels[c.status]||esc(c.status)}</span><h2>${esc(c.listing?.title||'交易物件')}</h2><p>${esc(c.listing?.city||'')}${esc(c.listing?.district||'')} · ${proposer?'我是提案方':'我是刊登／回覆方'}</p></div><strong>${Number(c.agreed_price).toLocaleString()} ${priceUnit(c.price_unit)}</strong></div><p class="transaction-terms">${esc(c.agreed_terms||'雙方未附加其他條件')}</p><a class="link" href="#/listing/${c.listing_id}" target="_blank" rel="noopener">查看物件</a><aside class="transaction-guidance"><strong>依物件類型核對</strong><p>${esc(transactionGuidance(c.listing||{}))}</p></aside>${c.status==='cancelled'?`<p class="notice">取消原因：${esc(c.cancellation_note)}</p>`:''}${c.status==='completed'?`<p class="transaction-success">✓ 雙方已確認所有核對事項，交易進度已結案。</p>`:''}${c.status==='pending'?`<p class="muted">此工作區由已接受的價格提案建立。任一方可開始共同核對。</p><button class="button primary small" data-case-action="start" data-case="${c.id}">開始交易核對</button>`:''}${c.status==='in_progress'?`<h3>雙方核對清單</h3><div class="transaction-progress-wrap"><div class="transaction-progress-label"><strong>${doneChecks}／${totalChecks} 項確認</strong><span>${progress}%</span></div><div class="transaction-progress-track" role="progressbar" aria-label="雙方交易核對完成度" aria-valuemin="0" aria-valuemax="${totalChecks}" aria-valuenow="${doneChecks}"><span style="width:${progress}%"></span></div><small>每項需買賣雙方各自確認；進度不代表款項已完成或法律文件有效。</small></div><div class="milestone-list">${milestones.map(m=>{const me=proposer?m.proposer_completed_at:m.owner_completed_at,them=proposer?m.owner_completed_at:m.proposer_completed_at;return `<div class="milestone-card"><div><strong>${esc(m.title)}</strong><p><span class="${me?'confirmed':''}">${me?'✓ 我已確認':'○ 等我確認'}</span><span class="${them?'confirmed':''}">${them?'✓ 對方已確認':'○ 等對方確認'}</span></p></div><button class="button small" data-case-action="milestone" data-case="${c.id}" data-milestone="${m.milestone_key}">${me?'取消我的確認':'確認完成'}</button></div>`}).join('')}</div><div class="transaction-actions">${allDone?`<button class="button primary small" data-case-action="complete" data-case="${c.id}" ${ownDone?'disabled':''}>${ownDone?'已確認結案，等候對方':'我確認交易完成'}</button>`:`<p class="muted">所有事項需由雙方各自確認後，才能進行結案確認。</p>`}<button class="button small" data-case-action="cancel" data-case="${c.id}">取消交易進度</button></div>`:''}</article>`}).join('')}</div>`:'<div class="empty"><h2>目前沒有交易進度</h2><p>雙方接受一筆出價／議價提案後，系統會自動建立核對工作區。</p><a class="button" href="#/offers">查看出價／議價</a></div>'}`;app.querySelectorAll('[data-case-action]').forEach(b=>b.onclick=async()=>{const action=b.dataset.caseAction;if(action==='complete'&&!confirm('只有雙方都確認完成後才會結案。確定送出你的確認？'))return;if(action==='cancel'){modal('取消交易進度',`<p class="muted">取消後此交易工作區會結束，請先和對方確認。</p><form id="transaction-cancel-form"><label class="modal-label">取消原因<textarea name="reason" maxlength="1000" minlength="3" required rows="4"></textarea></label><button class="button primary">確認取消</button></form>`);const f=$('#transaction-cancel-form');f.onsubmit=async e=>{e.preventDefault();const submit=f.querySelector('button');submit.disabled=true;try{const reason=new FormData(f).get('reason').trim();await result(db.rpc('haoju_update_transaction_case',{p_case_id:b.dataset.case,p_action:'cancel',p_milestone_key:null,p_cancellation_note:reason}));$('#info').close();toast('交易進度已取消');await route()}catch(err){toast(message(err));submit.disabled=false}};return}b.disabled=true;try{await result(db.rpc('haoju_update_transaction_case',{p_case_id:b.dataset.case,p_action:action,p_milestone_key:b.dataset.milestone||null,p_cancellation_note:null}));toast(action==='start'?'已開始交易核對':action==='milestone'?'已更新核對事項':action==='complete'?'已送出結案確認':'已更新');await route()}catch(err){toast(message(err));b.disabled=false}})}
async function offersPage(epoch){if(!requireUser())return;const rows=await result(db.from('transaction_offers').select('id,listing_id,proposer_id,owner_id,proposed_price,price_unit,terms,expires_at,status,parent_offer_id,created_at,updated_at,listing:listings(title,city,district,transaction_type,market_category,asking_price,monthly_rent)').or(`proposer_id.eq.${user.id},owner_id.eq.${user.id}`).order('updated_at',{ascending:false}).limit(200));if(epoch!==routeEpoch)return;const unit=x=>x==='monthly'?'元／月':x==='per_ping'?'元／坪':'元';app.innerHTML=`<section class="intro"><div><div class="eyebrow">OFFERS & NEGOTIATION</div><h1>出價與議價</h1><p>管理你提出的買賣／需求價格，也可對收到的提案接受、婉拒或提出反提案。</p></div></section>${rows.length?`<form id="offer-filters" class="offer-filters"><label>提案角色<select name="role"><option value="all">我提出與收到的</option><option value="received">我收到的</option><option value="sent">我提出的</option></select></label><label>處理狀態<select name="status"><option value="all">全部狀態</option><option value="open">待處理</option><option value="accepted">已接受</option><option value="closed">已結束</option></select></label><label>搜尋房源／條件<input name="q" maxlength="100" placeholder="房源、地點或提案內容"></label><button class="button small primary">套用</button><button class="button small" type="reset">清除</button></form><p id="offer-filter-count" class="muted"></p><div id="offer-filter-empty" class="empty" hidden><h2>沒有符合條件的提案</h2><p>調整搜尋字詞或清除篩選。</p></div><div class="application-list">${rows.map(o=>{const recipient=o.owner_id===user.id,expired=o.status==='pending'&&o.expires_at&&new Date(o.expires_at)<=new Date(),effectiveStatus=expired?'expired':o.status,searchText=[o.listing?.title,o.listing?.city,o.listing?.district,o.terms,o.proposed_price].filter(Boolean).join(' ').toLowerCase();return `<article class="rental-application-card offer-card" data-offer-card="${o.id}" data-offer-role="${recipient?'received':'sent'}" data-offer-status="${effectiveStatus}" data-offer-search="${esc(searchText)}"><div class="application-heading"><div><span class="tag">${o.status==='pending'&&o.expires_at&&new Date(o.expires_at)<=new Date()?'已過期':offerStatuses[o.status]||esc(o.status)}</span><h2>${esc(o.listing?.title||'物件')}</h2><p>${esc(o.listing?.city||'')}${esc(o.listing?.district||'')} · ${recipient?'收到提案':'我提出的提案'}</p></div><small>${new Date(o.created_at).toLocaleDateString('zh-TW')}</small></div><p class="offer-price">${Number(o.proposed_price).toLocaleString()} ${unit(o.price_unit)}</p><p class="pre-wrap">${esc(o.terms||'未附加其他條件')}</p>${o.parent_offer_id?'<p class="muted">↳ 此筆為反提案，前一筆條件仍保留在列表。</p>':'<p class="muted">初始提案</p>'}${o.expires_at?`<p class="muted">有效至 ${new Date(o.expires_at).toLocaleDateString('zh-TW')}</p>`:''}<div class="application-actions"><a class="button small" href="#/listing/${o.listing_id}" target="_blank" rel="noopener">查看物件</a>${o.status==='pending'&&o.expires_at&&new Date(o.expires_at)<=new Date()?`<button class="button small" data-offer-action="expire" data-offer="${o.id}">標記已過期</button>`:''}${recipient&&o.status==='pending'&&(!o.expires_at||new Date(o.expires_at)>new Date())?`<button class="button primary small" data-offer-action="accept" data-offer="${o.id}">接受</button><button class="button small" data-offer-action="counter" data-offer="${o.id}">提出反提案</button><button class="button small" data-offer-action="decline" data-offer="${o.id}">婉拒</button>`:''}${!recipient&&o.status==='pending'&&(!o.expires_at||new Date(o.expires_at)>new Date())?`<button class="button small" data-offer-action="withdraw" data-offer="${o.id}">撤回</button>`:''}${recipient&&o.status==='countered'?`<button class="button primary small" data-offer-action="accept" data-offer="${o.id}">接受反提案</button><button class="button small" data-offer-action="decline" data-offer="${o.id}">婉拒反提案</button>`:''}</div></article>`}).join('')}</div>`:'<div class="empty"><h2>目前沒有交易提案</h2><p>在可出售或求購的物件詳情提出價格與條件，雙方可在此追蹤議價狀態。</p><a class="button" href="#/buy">瀏覽物件</a></div>'}`;if(rows.length){const form=$('#offer-filters'),cards=[...app.querySelectorAll('[data-offer-card]')],empty=$('#offer-filter-empty'),count=$('#offer-filter-count'),apply=()=>{const role=form.querySelector('[name=role]').value,status=form.querySelector('[name=status]').value,q=form.querySelector('[name=q]').value.trim().toLowerCase();let visible=0;for(const card of cards){const state=card.dataset.offerStatus,statusOk=status==='all'||(status==='open'?['pending','countered'].includes(state):status==='accepted'?state==='accepted':['declined','withdrawn','expired'].includes(state)),show=(role==='all'||card.dataset.offerRole===role)&&statusOk&&(!q||card.dataset.offerSearch.includes(q));card.hidden=!show;if(show)visible++}count.textContent=`顯示 ${visible}／${cards.length} 筆提案；清單最多載入全部。`;empty.hidden=visible>0};form.onsubmit=e=>{e.preventDefault();apply()};form.onreset=()=>setTimeout(apply,0);apply()}app.querySelectorAll('[data-offer-action]').forEach(b=>b.onclick=async()=>{const action=b.dataset.offerAction;if(action==='accept'&&!confirm('確認接受此價格與條件？接受後請雙方再確認正式交易文件與付款安排。'))return;if(action==='decline'&&!confirm('確定婉拒這筆提案？'))return;if(action==='counter'){modal('提出反提案',`<form id="counter-offer-form"><label class="modal-label">新價格<input name="proposed_price" type="number" min="1" max="100000000000" required></label><label class="modal-label">補充條件<textarea name="terms" maxlength="3000" rows="4"></textarea></label><button class="button primary">送出反提案</button></form>`);const f=$('#counter-offer-form');f.onsubmit=async e=>{e.preventDefault();const submit=f.querySelector('button');submit.disabled=true;try{const v=Object.fromEntries(new FormData(f));await result(db.rpc('haoju_update_transaction_offer',{p_offer_id:b.dataset.offer,p_action:'counter',p_price:Number(v.proposed_price),p_terms:String(v.terms||'').trim(),p_expires_at:null}));$('#info').close();toast('反提案已送出');await route()}catch(err){toast(message(err));submit.disabled=false}};return}b.disabled=true;try{await result(db.rpc('haoju_update_transaction_offer',{p_offer_id:b.dataset.offer,p_action:action,p_price:null,p_terms:null,p_expires_at:null}));toast(action==='accept'?'已接受提案':action==='decline'?'已婉拒提案':action==='expire'?'已標記提案過期':'已撤回提案');await route()}catch(err){toast(message(err));b.disabled=false}})}
async function rentalApplications(epoch){if(!requireUser())return;const rows=await result(db.from('rental_applications').select('id,listing_id,tenant_id,owner_id,applicant_name,contact_phone,employment_type,monthly_income,occupants,move_in_date,lease_months,has_pets,smoker,introduction,status,created_at,updated_at,listing:listings(title,city,district,monthly_rent)').or(`tenant_id.eq.${user.id},owner_id.eq.${user.id}`).order('updated_at',{ascending:false}).limit(100));if(epoch!==routeEpoch)return;let agreements=[];const approved=rows.filter(r=>r.status==='approved');if(approved.length)agreements=await result(db.from('rental_agreements').select('id,application_id,status,updated_at').in('application_id',approved.map(r=>r.id)));const agreementByApplication=Object.fromEntries(agreements.map(a=>[a.application_id,a]));if(epoch!==routeEpoch)return;app.innerHTML=`<section class="intro"><div><div class="eyebrow">RENTAL APPLICATIONS</div><h1>租屋申請</h1><p>追蹤你提出的申請，或處理自己出租房源收到的申請。個人資料只會顯示給申請者與該房源屋主。</p></div></section>${rows.length?`<div class="application-list">${rows.map(r=>{const owner=r.owner_id===user.id;return `<article class="rental-application-card"><div class="application-heading"><div><span class="tag">${rentalApplicationStatuses[r.status]||esc(r.status)}</span><h2>${esc(r.listing?.title||'房源')}</h2><p>${esc(r.listing?.city||'')}${esc(r.listing?.district||'')} · ${r.listing?.monthly_rent?`${Number(r.listing.monthly_rent).toLocaleString()} 元／月`:''}</p></div><small>${owner?'收到的申請':'我提出的申請'} · ${new Date(r.created_at).toLocaleDateString('zh-TW')}</small></div><div class="application-facts"><p><strong>申請人：</strong>${esc(r.applicant_name)}</p><p><strong>聯絡電話：</strong><a href="tel:${encodeURIComponent(r.contact_phone)}">${esc(r.contact_phone)}</a></p><p><strong>工作／身份：</strong>${esc(r.employment_type)}</p><p><strong>月收入：</strong>${r.monthly_income==null?'未提供':`${Number(r.monthly_income).toLocaleString()} 元`}</p><p><strong>入住人數：</strong>${r.occupants} 人</p><p><strong>預計入住：</strong>${esc(r.move_in_date)}</p><p><strong>租期：</strong>${r.lease_months} 個月</p><p><strong>寵物／吸菸：</strong>${r.has_pets?'有寵物':'無寵物'}・${r.smoker?'吸菸':'不吸菸'}</p></div><div class="application-introduction"><strong>入住介紹</strong><p>${esc(r.introduction)}</p></div><div class="application-actions"><a class="button small" href="#/listing/${r.listing_id}" target="_blank" rel="noopener">查看房源</a>${r.status==='approved'?agreementByApplication[r.id]?`<a class="button primary small" href="#/rental-agreement/id/${agreementByApplication[r.id].id}">租賃條件：${esc(rentalAgreementStatuses[agreementByApplication[r.id].status]||agreementByApplication[r.id].status)}</a>`:owner?`<a class="button primary small" href="#/rental-agreement/application/${r.id}">建立租賃條件</a>`:`<span class="tag">等待屋主建立租賃條件</span>`:''}${owner&&r.status==='pending'?`<button class="button primary small" data-rental-status="approved" data-application="${r.id}">核准申請</button><button class="button small" data-rental-status="declined" data-application="${r.id}">婉拒</button>`:''}${!owner&&r.status==='pending'?`<button class="button small" data-rental-status="withdrawn" data-application="${r.id}">撤回申請</button>`:''}</div></article>`}).join('')}</div>`:'<div class="empty"><h2>目前沒有租屋申請</h2><p>登入後可在出租房源詳情提出申請，送出後可在此追蹤狀態。</p><a class="button" href="#/rent">開始找租屋</a></div>'}`;app.querySelectorAll('[data-rental-status]').forEach(button=>button.onclick=async()=>{const status=button.dataset.rentalStatus;if(status==='approved'&&!confirm('核准這位租客後，同一房源其他待審申請將自動婉拒。要繼續嗎？'))return;button.disabled=true;try{await result(db.rpc('haoju_update_rental_application',{p_application_id:button.dataset.application,p_status:status}));toast(status==='approved'?'已核准，其他待審申請已關閉':status==='declined'?'已婉拒申請':'已撤回申請');await rentalApplications(routeEpoch)}catch(err){toast(message(err));button.disabled=false}})}
async function requestViewing(p){if(!user){location.hash='#/account';return}modal('詢問／預約洽談',`<p>${esc(p.title)}・${esc(p.city)}${esc(p.district)}</p><form id="viewing-form"><label class="modal-label">希望參觀／洽談時間<input name="requested_at" type="datetime-local"></label><label class="modal-label">留言<textarea name="initial_message" required maxlength="2000" placeholder="介紹自己，或詢問房屋細節"></textarea></label><button class="button primary">送出詢問</button></form>`);$('#viewing-form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{const body=f.elements.initial_message.value.trim();if(!body)throw Error('請填寫留言');const row=await result(db.from('viewing_requests').insert({listing_id:p.id,requester_id:user.id,owner_id:p.owner_id,initial_message:body,requested_at:f.elements.requested_at.value?new Date(f.elements.requested_at.value).toISOString():null}).select('id').single());$('#info').close();toast('詢問已送出');location.hash='#/inquiry/'+row.id}catch(err){toast(message(err));b.disabled=false}}}
