$('#info .close').onclick=()=>{if(!busy)$('#info').close()};$('#info').addEventListener('cancel',e=>{if(busy)e.preventDefault()});
document.addEventListener('click',e=>{const clearHistory=e.target.closest('#clear-recent-searches');if(clearHistory){try{localStorage.removeItem('haoju-recent-searches-v1')}catch{}route();return}const recent=e.target.closest('[data-recent-search]');if(recent){const item=readRecentSearches()[Number(recent.dataset.recentSearch)];if(item){Object.assign(filters,defaultFilters,recentCriteria(item),{page:0});activeSavedSearchId=null;activeSavedSearchMarket=null;if(marketView()!==item.market)location.hash='#/'+item.market;else route()}return}const link=e.target.closest('a[href^="#/"]');if(link){if(busy){e.preventDefault();toast('請等待目前的儲存完成');return}if(dirty&&!confirm('尚有未儲存變更，確定離開？')){e.preventDefault();return}if(link.hash!==location.hash){if(link.hasAttribute('data-urgent-shortcut'))Object.assign(filters,defaultFilters,{deal:'sale',urgentOnly:'urgent',tags:[],page:0});else if(Object.prototype.hasOwnProperty.call(marketViews,link.hash.slice(2)))Object.assign(filters,defaultFilters,{tags:[],page:0});else filters.page=0}dirty=false}const fav=e.target.closest('[data-fav]');if(fav)toggleFavorite(fav.dataset.fav,fav);const compare=e.target.closest('[data-compare]');if(compare){const id=compare.dataset.compare;if(compareSet.has(id))compareSet.delete(id);else if(compareSet.size<3)compareSet.add(id);else toast('一次最多比較三筆物件');persistCompareSet();if(!busy)route()}const draft=e.target.closest('[data-draft]');if(draft)changeStatus(draft.dataset.draft,'draft');const archive=e.target.closest('[data-archive]');if(archive)changeStatus(archive.dataset.archive,'archived');const sold=e.target.closest('[data-mark-sold]');if(sold){if(!confirm('確認將這筆刊登標記為已成交？成交案件會從公開房源移除，但資料仍保留在你的會員中心。'))return;sold.disabled=true;result(db.from('listings').update({status:'archived',deal_status:'sold'}).eq('id',sold.dataset.markSold).eq('owner_id',user.id).select('id')).then(rows=>{if(!rows.length)throw Error('房源不存在或無權限');toast('案件已標記成交');route()}).catch(err=>{toast(message(err));sold.disabled=false})}});
