$('#about').onclick=()=>modal('關於好居','<p>好居提供租屋、買屋、新建案、土地及商用物件搜尋與刊登，也提供官方成交行情彙總。房源由刊登者提供，完成審核後才會公開。</p>');$('#nav-toggle').onclick=e=>{const open=e.currentTarget.getAttribute('aria-expanded')!=='true';e.currentTarget.setAttribute('aria-expanded',String(open));$('#primary-navigation').classList.toggle('nav-open',open)};$('#nav-more-toggle').onclick=e=>{const open=e.currentTarget.getAttribute('aria-expanded')!=='true';e.currentTarget.setAttribute('aria-expanded',String(open));$('#nav-more-menu').parentElement.classList.toggle('menu-open',open)};document.addEventListener('click',e=>{if(!e.target.closest('.nav-more')){$('#nav-more-toggle')?.setAttribute('aria-expanded','false');$('#nav-more-menu')?.parentElement.classList.remove('menu-open')}});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#nav-more-toggle')?.setAttribute('aria-expanded','false');$('#nav-more-menu')?.parentElement.classList.remove('menu-open');$('#primary-navigation').classList.remove('nav-open');$('#nav-toggle')?.setAttribute('aria-expanded','false')}});document.querySelectorAll('#primary-navigation a').forEach(a=>a.addEventListener('click',()=>{$('#nav-more-toggle')?.setAttribute('aria-expanded','false');$('#nav-more-menu')?.parentElement.classList.remove('menu-open');const toggle=$('#nav-toggle');toggle?.setAttribute('aria-expanded','false');$('#primary-navigation').classList.remove('nav-open')}));$('#privacy').onclick=()=>modal('資料與隱私','<p>帳號、收藏、房源與照片儲存在好居使用的 Supabase 專案。瀏覽器會保存登入狀態，使用共用電腦後請登出。</p><p>公開房源資訊與照片可供訪客瀏覽；聯絡資料僅供登入會員查看。請勿在房源說明或照片中放入不打算公開的個人資料。</p>');
async function boot(){try{if(!window.HaojuSupabase?.createClient||!cfg)throw Error('網站設定或 Supabase 程式未載入，請確認上傳的檔案完整。');db=window.HaojuSupabase.createClient(cfg.supabaseUrl,cfg.publishableKey,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true,storageKey:'haoju-auth-v1'}});db.auth.onAuthStateChange((event,session)=>{const previous=user?.id;user=session?.user||null;if(event==='PASSWORD_RECOVERY'){recovery=true;history.replaceState(null,'',location.pathname+'#/account')}if(event==='SIGNED_OUT'){saved.clear();recovery=false}header();if(event!=='INITIAL_SESSION'&&(event==='PASSWORD_RECOVERY'||previous!==user?.id)){clearTimeout(authTimer);authTimer=setTimeout(async()=>{try{await loadFavorites();await refreshUnreadNotifications();if(!busy&&!dirty)await route()}catch(e){toast(message(e))}},0)}});const d=await result(db.auth.getSession());user=d.session?.user||null;await refreshAdmin();if(new URLSearchParams(location.search).has('recovery')&&user){recovery=true;history.replaceState(null,'',location.pathname+'#/account')}if(location.hash.includes('error_description=')){const params=new URLSearchParams(location.hash.slice(1));toast(params.get('error_description')||'登入連結無效');history.replaceState(null,'',location.pathname+'#/account')}await loadFavorites();await refreshUnreadNotifications();await route()}catch(e){errorPage(e)}}
boot();
async function officialMarketPage(epoch){const city=$('#market-city')?.value||'',district=$('#market-district')?.value||'',subject=$('#market-subject')?.value||'',months=Number($('#market-months')?.value||12),stats=await result(db.rpc('haoju_official_market_stats',{p_city:city?(officialCountyNames[city]||city):null,p_district:district||null,p_subject:subject||null,p_months:months}));if(epoch!==routeEpoch)return;const subjects=['土地','房地(土地+建物)','房地(土地+建物)+車位','建物','車位'];app.innerHTML=`<div class="breadcrumb"><a href="#/rent">找房</a> ／ 成交行情</div><section class="intro"><div><div class="eyebrow">OFFICIAL TRANSACTION DATA</div><h1>實價成交行情</h1><p>依內政部公開成交資料彙整中位數；這是歷史成交參考，並非即時開價或估價。</p></div></section><section class="panel market-filters"><form id="market-filter" class="advanced-grid"><label>縣市<select id="market-city"><option value="">全部縣市</option>${cities.map(c=>`<option ${c===city?'selected':''}>${c}</option>`).join('')}</select></label><label>行政區<input id="market-district" maxlength="20" value="${esc(district)}" placeholder="例如：大安區"></label><label>交易標的<select id="market-subject"><option value="">全部類型</option>${subjects.map(k=>`<option ${k===subject?'selected':''}>${k}</option>`).join('')}</select></label><label>統計期間<select id="market-months">${[1,3,6,12,24,60].map(n=>`<option value="${n}" ${n===months?'selected':''}>近 ${n} 個月</option>`).join('')}</select></label><button class="button primary">更新行情</button></form></section><section class="market-summary"><article class="panel"><span>成交筆數</span><strong>${Number(stats?.transaction_count||0).toLocaleString()}</strong></article><article class="panel"><span>成交總價中位數</span><strong>${stats?.median_total_price?`${Number(stats.median_total_price).toLocaleString()} 元`:city&&subject?'樣本不足':'請選縣市與交易類型'}</strong></article><article class="panel"><span>成交單價中位數</span><strong>${stats?.median_unit_price_ping?`${Number(stats.median_unit_price_ping).toLocaleString()} 元／坪`:city&&subject?'樣本不足':'請選縣市與交易類型'}</strong></article></section><section class="panel"><h2>月成交走勢</h2>${(stats?.monthly||[]).length?`<div class="market-chart">${stats.monthly.map(m=>{const max=Math.max(...stats.monthly.map(x=>Number(x.transaction_count||0)),1),width=Math.max(3,Math.round(Number(m.transaction_count)/max*100));return `<div class="market-month"><span>${esc(String(m.month).slice(0,7))}</span><div class="market-bar" style="width:${width}%" title="${m.transaction_count} 筆"></div><small>${Number(m.transaction_count).toLocaleString()} 筆${m.median_unit_price_ping?` · ${Number(m.median_unit_price_ping).toLocaleString()} 元／坪`:''}</small></div>`}).join('')}</div>`:'<p class="muted">目前沒有符合條件的公開成交資料。</p>'}<p class="muted">資料時間：${stats?.first_transaction_date?`${esc(stats.first_transaction_date)} 至 ${esc(stats.last_transaction_date)}`:'尚無成交日期'} · 最近匯入：${stats?.last_imported_at?esc(new Date(stats.last_imported_at).toLocaleDateString('zh-TW')):'尚無資料'}</p>${stats?.latest_batch?`<small>最近批次：${esc(stats.latest_batch.release_note)} · ${Number(stats.latest_batch.row_count).toLocaleString()} 筆 / ${stats.latest_batch.county_count} 縣市</small>`:''}</section><section class="panel"><h2>行情解讀</h2><p>成交單價以內政部資料的每平方公尺單價換算為每坪。請先選縣市與交易標的，且總價／單價各自至少 5 筆有效樣本才會顯示中位數，避免跨縣市、跨標的混算。土地、建物、含車位交易的價格組成可能不同，使用前請比較交易標的與實際條件。</p><p>資料來源：<a href="https://plvr.land.moi.gov.tw/DownloadOpenData" target="_blank" rel="noopener noreferrer">內政部不動產成交案件實際資訊資料供應系統 ↗</a> · 政府資料開放授權條款第 1 版</p></section>`;$('#market-filter').onsubmit=e=>{e.preventDefault();officialMarketPage(epoch).catch(errorPage)}}
async function officialImportPage(epoch){if(!requireUser())return;if(!isAdmin){app.innerHTML='<div class="empty"><h2>此頁僅供好居管理員使用</h2></div>';return}app.innerHTML=`<div class="breadcrumb"><a href="#/admin">管理後台</a> ／ 匯入成交行情</div><section class="intro"><div><div class="eyebrow">ADMIN DATA IMPORT</div><h1>匯入官方成交資料</h1><p>先從政府資料集下載最新「不動產買賣實價登錄批次資料」ZIP，再選取原始 ZIP；網站只匯入各縣市主 CSV，分批寫入並保留來源批次。</p></div></section><section class="panel"><p><a class="button" href="https://plvr.land.moi.gov.tw/DownloadOpenData" target="_blank" rel="noopener noreferrer">前往內政部下載資料 ↗</a></p><label>政府資料 ZIP<input id="official-zip" type="file" accept=".zip,application/zip"></label><label>資料批次名稱<input id="official-release" maxlength="500" value="${new Date().toISOString().slice(0,10)} 內政部實價登錄批次"></label><button id="start-official-import" class="button primary">開始匯入</button><p id="official-import-status" role="status" aria-live="polite">單次匯入會逐批上傳，完成後才公開統計結果。請保持此頁開啟。</p></section><section class="panel"><h2>資料來源與隱私</h2><p>政府原始資料含交易位置資訊；Supabase 不允許一般訪客讀取逐筆資料，行情頁只顯示彙總中位數。</p><p>匯入需管理員登入。SQL migration 006 必須先在 Supabase 執行，此畫面不會自行建立資料表。</p></section>`;$('#start-official-import').onclick=async e=>{const button=e.currentTarget,file=$('#official-zip').files?.[0],note=$('#official-release').value.trim(),status=$('#official-import-status');if(!file){status.textContent='請先選取內政部下載的 ZIP 檔。';return}if(file.size>50*1024*1024){status.textContent='ZIP 檔超過 50 MB 上限。';return}if(!window.fflate?.unzipSync){status.textContent='壓縮檔模組未載入，請確認完整上傳網站檔案。';return}button.disabled=true;let batchKey='';try{status.textContent='正在解壓縮與驗證 CSV…';const bytes=new Uint8Array(await file.arrayBuffer()),digest=await crypto.subtle.digest('SHA-256',bytes);batchKey=[...new Uint8Array(digest)].map(v=>v.toString(16).padStart(2,'0')).join('');const files=window.fflate.unzipSync(bytes),decode=b=>new TextDecoder('utf-8').decode(b).replace(/^\uFEFF/,''),names=Object.keys(files),manifestName=names.find(n=>n.toLowerCase().endsWith('manifest.csv'));if(!manifestName)throw Error('ZIP 內找不到 manifest.csv，請確認是官方批次資料 ZIP。');const manifest=parseCSV(decode(files[manifestName]));if(!manifest.length)throw Error('manifest.csv 是空的。');const mh=manifest[0].map(x=>x.trim().toLowerCase()),nameIndex=Math.max(0,mh.findIndex(x=>['name','filename','檔案名稱'].includes(x))),cityIndex=Math.max(1,mh.findIndex(x=>['description','city','縣市'].includes(x))),cityByFile=new Map(manifest.slice(1).map(r=>[r[nameIndex],String(r[cityIndex]||'').replace(/不動產買賣.*$/,'').replace(/﻿/g,'').trim()]));let rows=[],done=0,skipped=0;const csvFiles=names.filter(n=>/(?:^|\/)\w_lvr_land_a\.csv$/i.test(n));if(!csvFiles.length)throw Error('找不到縣市主交易 CSV。');for(let fi=0;fi<csvFiles.length;fi++){const filename=csvFiles[fi],csv=parseCSV(decode(files[filename]));if(csv.length<3)continue;const columns=Object.fromEntries(csv[0].map((k,i)=>[k.trim(),i])),county=cityByFile.get(filename.split('/').pop())||cityByFile.get(filename)||'';for(const sourceRow of csv.slice(2)){const item=officialTransaction(sourceRow,columns,county);if(item){rows.push(item);if(rows.length===250){await result(db.rpc('haoju_import_official_transactions',{p_batch_key:batchKey,p_release_note:note,p_rows:rows}));done+=rows.length;rows=[];status.textContent=`匯入中… ${done.toLocaleString()} 筆（${fi+1}/${csvFiles.length} 縣市檔）`}}else skipped++}}if(rows.length){await result(db.rpc('haoju_import_official_transactions',{p_batch_key:batchKey,p_release_note:note,p_rows:rows}));done+=rows.length}if(!done)throw Error('沒有找到有效成交列，尚未發布行情。');status.textContent=`已匯入 ${done.toLocaleString()} 筆，正在核對並發布批次…`;const finalized=await result(db.rpc('haoju_finalize_official_batch',{p_batch_key:batchKey}));status.textContent=`完成：${Number(finalized.row_count).toLocaleString()} 筆、${finalized.county_count} 縣市，交易日期 ${finalized.first_date} 至 ${finalized.last_date}。略過 ${skipped.toLocaleString()} 列。`}catch(error){status.textContent=`匯入未完成：${message(error)}${batchKey?' 已寫入的資料尚未公開；修正後請重選相同 ZIP 重試。':''}`}finally{button.disabled=false}}}
